874	function timelineHtml(agents, all, opts) {
875	  const now = Date.now(); const HOURS = 48; const t0 = now - HOURS * 3600000; const pxh = 26; const W = HOURS * pxh;
876	  const byFn = !!(opts && opts.byFn); // 派发制：按职能分泳道——一次性主办不占行，行数恒定
877	  const online = byFn ? [] : agents.filter((a) => a.上线 !== false).map((a) => a.id);
878	  const withSegs = all.filter((t) => t.主办 && t.领单时间);
879	  const laneOf = (t) => byFn ? (t.职能 || '其他') : t.主办;
880	  // 泳道 = 数据里真实出现的职能（施工令-027）：FN_ORDER 只当"排序偏好"，不当"白名单"——
881	  // 写死六项的年代，新增职能（技术策划）的在途单泳道会被 filter 直接滤掉，人在时间轴上凭空消失。
882	  const FN_ORDER = ['策划', '技术策划', '程序', '美术', '装配', 'QA', '其他'];
883	  const 出现的职能 = [...new Set(withSegs.map((t) => t.职能 || '其他'))];
884	  const ids = byFn
885	    ? [...FN_ORDER.filter((fn) => 出现的职能.includes(fn)), ...出现的职能.filter((fn) => !FN_ORDER.includes(fn)).sort()]
886	    : [...new Set([...online, ...withSegs.map((t) => t.主办)])];
887	  const segs = {}; let any = false;
888	  for (const t of withSegs) {
889	    const s = Date.parse(t.领单时间); if (Number.isNaN(s)) continue;
890	    const inflight = ['在途', '质检', '待定夺'].includes(t.state);
891	    const e = t.交付时间 ? Date.parse(t.交付时间) : (inflight ? now : null);
892	    if (e == null || e < t0) continue;
893	    any = true;
894	    const lane = laneOf(t);
895	    (segs[lane] = segs[lane] || []).push({ s: Math.max(s, t0), e: Math.min(e, now), t, inflight });
896	  }
897	  const head = `<b style="font-size:13px">执行时间轴</b><span class="subnote" style="margin-left:12px">最近 48 小时 · 右缘=现在 · 段=领单→交付</span>`;
898	  if (!any) return `<div class="tlcard card r14">${head}
899	    <div class="emptycard" style="margin-top:14px"><h5>还没有执行记录</h5>
900	    <p>agent 领单执行后，这里按人回放每一段真实执行（领单 → 交付），瓶颈自己浮出来。</p></div></div>`;
901	  let ticks = '';
902	  for (let h = 0; h <= HOURS; h += 6) { const x = W - h * pxh; const d = new Date(now - h * 3600000);
903	    ticks += `<span class="tltick" style="left:${x}px">${String(d.getHours()).padStart(2, '0')}:00</span>`; }
904	  let si = 0; // 段序号：入场按序生长（左→右错峰 40ms，封顶 12 档）
905	  const laneLevels = {}; // 职能泳道内并行段堆叠：贪心装层，防重叠
906	  if (byFn) {
907	    for (const id of ids) {
908	      const arr = (segs[id] || []).sort((a, b) => a.s - b.s);
909	      const levelEnds = [];
910	      for (const g of arr) {
911	        let lv = levelEnds.findIndex((end) => end <= g.s);
912	        if (lv < 0) { lv = levelEnds.length; levelEnds.push(0); }
913	        levelEnds[lv] = g.e + 60000; g.lv = lv;
914	      }
915	      laneLevels[id] = Math.max(1, levelEnds.length);
916	    }
917	  }
918	  const rowH = (id) => byFn ? (laneLevels[id] || 1) * 30 : 30; // 整行占位（含 8px 外边距）
919	  const laneH = (id) => rowH(id) - 8;
920	  const lanes = ids.map((id) => `<div class="tllane" style="height:${laneH(id)}px">${(segs[id] || []).map((g) => {
921	    const x = (g.s - t0) / 3600000 * pxh; const w = Math.max(6, (g.e - g.s) / 3600000 * pxh);
922	    const c = FNHEX[g.t.职能] || 'var(--ink3)';
923	    const label = byFn && w >= 44 ? `<i class="tlseglb">${esc(g.t.id.replace(/^TK-/, ''))}</i>` : '';
924	    // 在途 ❄（施工令-021）：冻结段既不是「进行中」也不是「已交付」，标题里如实说第三种
925	    return `<span class="tlseg ${g.inflight ? 'on' : ''}${suspCls(g.t)}" style="--i:${si++};left:${x}px;width:${w}px;background:${c}${byFn ? `;top:${3 + (g.lv || 0) * 30}px` : ''}" title="${esc(g.t.id)} ${esc(g.t.title)}（${suspOf(g.t) ? '已挂起' : g.inflight ? '进行中' : '已交付'}）${suspOf(g.t) ? '\n' + esc(suspTip(g.t)) : ''}" onclick="location.hash='#/t/${esc(g.t.id)}'">${suspOf(g.t) ? '<i class="tlseglb snowb">❄</i>' : label}</span>`;
926	  }).join('')}</div>`).join('');
927	  const colH = ids.reduce((a, id) => a + rowH(id), 0);
928	  setTimeout(() => { const el = $('tlscroll'); if (el) el.scrollLeft = el.scrollWidth; }, 0);
929	  return `<div class="tlcard card r14">${head}
930	    <div class="tlflex"><div class="tlwhocol"><div class="tlsp"></div>${ids.map((id) => `<div class="tlwho" style="height:${rowH(id)}px">${esc(id)}</div>`).join('')}</div>
931	    <div class="tlscroll" id="tlscroll"><div style="position:relative;width:${W + 20}px">
932	      <div class="tlaxis">${ticks}</div>${lanes}
933	      <div class="tlnow" style="left:${W - 1}px;height:${20 + colH}px"></div>
934	    </div></div></div></div>`;
935	}
936	/* ===== 在途 · 派发制视图（H49）：执行者因单而生、完成即销毁，常备的只有审检 ===== */
937	// 进度渲染三件套（施工令-004）：口径全在服务端 lib/progress.js 算好，这里只负责画。
938	const 进度态 = (p) => (p && p.超时 ? 'warn' : p && p.判官 ? 'judge' : '');
939	function segbarHtml(p, id) {
940	  const cls = 进度态(p);
941	  return `<div class="segbar"${id ? ` id="${esc(id)}"` : ''}>${((p && p.段) || []).map((s) => `<div class="seg ${s.态}${s.态 === 'cur' && cls ? ' ' + cls : ''}">
942	      <i>${s.态 === 'cur' ? `<em style="--fill:${Math.round((s.填充 || 0) * 100)}%"></em>` : ''}</i><span>${esc(s.名)}</span></div>`).join('')}</div>`;
943	}
944	// 计时：判官阶段报「本步 · 全程」，执行阶段报「已跑 · 预估」（超时转红，一眼可捞）
945	// 施工令-041 §四：这一行是**时长**，不是进度。原样式写「已跑 24分 / 预估 50分」，那道斜杠
946	// 被当成分数读（巡礼 F2：同一张单头上 28%、这行读出 49%），改成「·」分隔并直书「时长」二字，
947	// 页面上关于进度的百分比从此只有卡头那一个数。
948	function 计时Html(p, 环节起时, 领单时间) {
949	  const tm = (iso, over) => iso && !Number.isNaN(Date.parse(iso))
950	    ? `<span class="tm${over ? ' over' : ''}" data-since="${esc(iso)}">${fmtElapsed(Date.now() - Date.parse(iso))}</span>` : '<span>--:--</span>';
951	  if (p && p.判官) return `${tm(环节起时)} 本步${领单时间 ? ` · ${tm(领单时间)} 全程` : ''}`;
952	  const est = p && p.预估分钟 ? fmtElapsed(p.预估分钟 * 60000) : null;
953	  return `已跑 ${tm(环节起时 || 领单时间, !!(p && p.超时))}${est ? ` · 预估 ${est}<span class="tmnote">（时长）</span>` : '<span class="tmnote">（无预估）</span>'}`;
954	}
955	// 百分比的出处（施工令-041 §四）：打点 → 「打点 3/7」；无打点 → 「阶段锚点（无打点）」。
956	// 悬浮说得出这个数怎么来的，才谈得上信任；两页共用这一句，口径不许各说各话。
957	function pctTitle(p) {
958	  const q = p || {};
959	  if (q.打点) return `会话打点 ${q.打点.k}/${q.打点.n} · ${q.阶段名 || ''}`;
960	  return `${q.阶段名 || ''} · 阶段锚点${q.锚点 != null ? ' ' + q.锚点 + '%' : ''}（本阶段无会话打点，不按耗时折算）`;
961	}
962	// 无会话已等时长（建设性①）：基准取「进本状态的时刻」= 更新时间，回落领单时间。
963	// 用更新时间而非领单时间，是因为质检态无会话时领单时间早已过期，报出来的分钟数会失真。
964	function 无会话分钟(r) {
965	  const t = Date.parse(r.更新时间 || r.领单时间 || '');
966	  return Number.isNaN(t) ? null : Math.max(0, Math.round((Date.now() - t) / 60000));
967	}
968	// 右列内容（百分比+阶段名+计时）：整块可原地重画，活体轮询只换这一块
969	function pctHtml(r) {
