// probe.js — Electron DOM 探针：真实命中区量测（含伪元素扩区，用 elementsFromPoint 逐像素探边界）
// 跑法：node_modules/.bin/electron probe.js  （需先起 serve.js）
const { app, BrowserWindow } = require('electron');
const fs = require('fs');
const path = require('path');

app.disableHardwareAcceleration();
app.commandLine.appendSwitch('disable-gpu');

const BASE = 'http://127.0.0.1:4299/';
const ROUTES = ['agents', 'relay', 'wiki', 'board', 'flow', 'report'];
const OUT = path.join(__dirname, process.argv.includes('--after') ? 'after.json' : 'before.json');

const PROBE = `(() => {
  const FLOOR = 26;
  const SEL = 'a[href],button,summary,input,select,textarea,[onclick],[role="button"],[tabindex]';
  const els = [...document.querySelectorAll(SEL)].filter((el) => {
    const r = el.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return false;
    const cs = getComputedStyle(el);
    return cs.visibility !== 'hidden' && cs.display !== 'none';
  });
  const sig = (el) => el.tagName.toLowerCase() + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\\s+/).join('.') : '');
  const measure = (el) => {
    el.scrollIntoView({ block: 'center', inline: 'center' });
    const r = el.getBoundingClientRect();
    const cx = Math.round(r.left + r.width / 2), cy = Math.round(r.top + r.height / 2);
    const hitAt = (x, y) => { const s = document.elementsFromPoint(x, y); return s.includes(el); };
    if (!hitAt(cx, cy)) return null;
    let up = cy, dn = cy, lf = cx, rt = cx;
    for (let y = cy; y > cy - 60 && hitAt(cx, y); y--) up = y;
    for (let y = cy; y < cy + 60 && hitAt(cx, y); y++) dn = y;
    for (let x = cx; x > cx - 60 && hitAt(x, cy); x--) lf = x;
    for (let x = cx; x < cx + 60 && hitAt(x, cy); x++) rt = x;
    return { h: dn - up + 1, w: rt - lf + 1, rh: Math.round(r.height), rw: Math.round(r.width) };
  };
  const bad = [], skipped = [];
  const tally = {};
  for (const el of els) {
    const m = measure(el);
    if (!m) { skipped.push(sig(el)); continue; }
    if (m.h < FLOOR || m.w < FLOOR) {
      const k = sig(el);
      bad.push({ k, h: m.h, w: m.w, rh: m.rh, rw: m.rw, tx: (el.textContent || '').trim().slice(0, 18) });
      tally[k] = (tally[k] || 0) + 1;
    }
  }
  const R = { 候选: els.length, 不达标: bad.length, 未量到: skipped.length, 明细: tally, 样本: bad.slice(0, 60) };
  // ---- 逐项专用读数 ----
  const h = location.hash;
  if (h.indexOf('flow') >= 0) {
    R.flow = { 管线行: document.querySelectorAll('.fglane').length,
      空态行: document.querySelectorAll('.fgidle').length,
      空态文: [...document.querySelectorAll('.fgidle')].map((x) => x.textContent.trim().slice(0, 30)),
      沉淀钮: document.querySelectorAll('.fgcat').length };
  }
  if (h.indexOf('board') >= 0) {
    const cols = [...document.querySelectorAll('.bcol2')].map((c) => ({
      名: (c.querySelector('h4') || {}).textContent ? c.querySelector('h4').textContent.trim().slice(0, 20) : '',
      卡: c.querySelectorAll('.bcard2').length }));
    R.board = { 列: cols, 展开钮: [...document.querySelectorAll('button')].filter((b) => /展开全部|收起/.test(b.textContent)).map((b) => b.textContent.trim()) };
  }
  if (h.indexOf('report') >= 0) {
    R.report = [...document.querySelectorAll('.rp-card')].map((c) => {
      const head = (c.querySelector('h4') || {}).textContent || '';
      const rows = [...c.querySelectorAll('tr')].map((tr) => [...tr.children].map((td) => td.textContent.trim()));
      return { 卡: head.trim().slice(0, 24), 行: rows };
    }).filter((x) => /按职能|项目管理台账/.test(x.卡));
  }
  return R;
})()`;

app.whenReady().then(async () => {
  const win = new BrowserWindow({ show: false, width: 1600, height: 1000, webPreferences: { backgroundThrottling: false } });
  const out = {};
  await win.loadURL(BASE);
  await new Promise((r) => setTimeout(r, 2500));
  for (const route of ROUTES) {
    await win.webContents.executeJavaScript(`location.hash = '#/${route}'; 1`);
    await new Promise((r) => setTimeout(r, 2200));
    try {
      out[route] = await win.webContents.executeJavaScript(PROBE);
    } catch (e) { out[route] = { error: String(e && e.message || e) }; }
    console.log(route, JSON.stringify({ 候选: out[route].候选, 不达标: out[route].不达标 }));
  }
  fs.writeFileSync(OUT, JSON.stringify(out, null, 2), 'utf8');
  console.log('WROTE ' + OUT);
  app.quit();
}).catch((e) => { console.error(e); app.quit(); });

