  const s = sel.replace(/::?[\w-]+(\([^)]*\))?/g, ''); // 伪类/伪元素不计
  return [(s.match(/#/g) || []).length, (s.match(/\./g) || []).length + (s.match(/\[/g) || []).length,
    (s.match(/(^|[\s>+~])[a-zA-Z]/g) || []).length];
}
function compoundMatch(c, node) {
  const tagM = c.match(/^[a-zA-Z][\w-]*/);
  if (tagM && node.tag !== tagM[0].toLowerCase()) return false;
  for (const cl of c.match(/\.[\w-]+/g) || []) if (!node.cls.includes(cl.slice(1))) return false;
  for (const at of c.match(/\[[^\]]+\]/g) || []) {
    const mm = at.slice(1, -1).match(/^([\w-]+)(?:([~^$*|]?=)"?([^"\]]*)"?)?$/);
    if (!mm) return false;
    const v = node.attrs[mm[1].toLowerCase()];
    if (v == null) return false;
    if (mm[2] === '=' && v !== mm[3]) return false;
  }
  return true;
}
// 只支持后代/子组合器；伪类（:hover/:not(...)）整段剥掉后按剩余匹配（:hover 类规则单独标记不计）
function selMatch(sel, node) {
  if (/:(hover|focus|active|focus-visible)/.test(sel)) return false;
  const clean = sel.replace(/::[\w-]+/g, '').replace(/:[\w-]+(\([^)]*\))?/g, '');
  const parts = clean.trim().split(/\s*>\s*|\s+/).filter(Boolean);
  if (!parts.length) return false;
  if (!compoundMatch(parts[parts.length - 1], node)) return false;
  let idx = node.chain.length - 1;
  for (let p = parts.length - 2; p >= 0; p--) {
    let hit = -1;
    for (let k = idx; k >= 0; k--) if (compoundMatch(parts[p], node.chain[k])) { hit = k; break; }
    if (hit < 0) return false;
    idx = hit - 1;
  }
  return true;
}
function computed(node) {
  const hits = RULES.filter((r) => selMatch(r.sel, node))
    .map((r) => ({ r, sp: specificity(r.sel) }))
    .sort((a, b) => a.sp[0] - b.sp[0] || a.sp[1] - b.sp[1] || a.sp[2] - b.sp[2] || a.r.order - b.r.order);
  const out = {};
  for (const h of hits) Object.assign(out, h.r.decls);
  // 行内 style 最高
  for (const d of (node.attrs.style || '').split(';')) {
    const c = d.indexOf(':');
    if (c > 0) out[d.slice(0, c).trim()] = d.slice(c + 1).trim();
  }
  return { decls: out, sels: hits.map((h) => h.r.sel) };
}
// ::after / ::before 扩区（position:absolute + 明确 height）：算真实可点高度
function pseudoBox(node) {
  let best = 0;
  for (const r of RULES) {
    if (!/::(after|before)\s*$/.test(r.sel)) continue;
    const base = r.sel.replace(/::(after|before)\s*$/, '').trim();
    if (!selMatch(base, node)) continue;
    if ((r.decls.position || '') !== 'absolute') continue;
    const h = px(r.decls.height);
    if (h) best = Math.max(best, h);
  }
  return best;
}
const px = (v) => { const m = /^(-?[\d.]+)px$/.exec(String(v || '').trim()); return m ? parseFloat(m[1]) : 0; };
function boxH(node) {
  const { decls, sels } = computed(node);
  const fs2 = px(decls['font-size']) || ROOT_FS;
  let lh;
  const lhv = String(decls['line-height'] || '').trim();
  if (/px$/.test(lhv)) lh = px(lhv);
  else if (lhv && !isNaN(parseFloat(lhv))) lh = parseFloat(lhv) * fs2;
  else lh = Math.round(fs2 * 1.5);
  const padY = ((p) => {
    const s = String(p || '').trim().split(/\s+/);
    const t = px(decls['padding-top'] || (s[0] || 0));
    const b = px(decls['padding-bottom'] || (s.length > 2 ? s[2] : s[0]) || 0);
    return t + b;
  })(decls.padding);
  const bw = 2 * px(String(decls.border || '').split(/\s+/)[0]);
  const content = lh + padY + bw;
  const explicit = px(decls.height);
  const minH = px(decls['min-height']);
  const own = explicit || Math.max(content, minH);
  return { h: Math.max(own, pseudoBox(node)), own, pseudo: pseudoBox(node), fs: fs2, lh, padY, sels: sels.slice(-4) };
}

/* ---------- 4. 跑 ---------- */
const pages = fs.readdirSync(DIR).filter((f) => f.endsWith('.html'));
const report = {};
for (const f of pages) {
  const nodes = parseHtml(fs.readFileSync(path.join(DIR, f), 'utf8')).filter(interactive);
  const groups = {};
  for (const n of nodes) {
    const k = sigOf(n);
    if (!groups[k]) groups[k] = { n: 0, box: boxH(n) };
    groups[k].n++;
  }
  const bad = Object.entries(groups).filter(([, g]) => g.box.h < FLOOR)
    .sort((a, b) => b[1].n - a[1].n);
  report[f.replace('.html', '')] = {
    交互元素: nodes.length,
    不达标实例: bad.reduce((a, [, g]) => a + g.n, 0),
    不达标签名: bad.map(([k, g]) => `${k} ×${g.n} → ${g.box.h}px (own ${g.box.own}, pseudo ${g.box.pseudo})`),
  };
}
console.log(JSON.stringify(report, null, 2));
fs.writeFileSync(path.join(__dirname, process.argv.includes('--after') ? 'touch-after.json' : 'touch-before.json'), JSON.stringify(report, null, 2), 'utf8');

