  return top + `<div class="fgboard" id="fg-board">
      <div class="fgcols"><div>管线</div><div class="nowh">◉ 现在在做</div><div>→ 接下来（依赖序 → 计划）</div></div>
      ${laneHtml}${维护Html}</div>` + legend;
