let qOpen = {}; // 批名 → 用户是否手动展开/折叠（3s 脉冲重画会重进本函数，不记住的话折叠状态每 3 秒被打回原形）
const QCLS = { 计划: 'plan', 起草中: 'draft', 已成单: 'made', 完成: 'done', 撤销: 'drop' };
function qRow(c) {
  const 终 = ['完成', '撤销'].includes(c.状态);
  // 单号在手就链过去（已成单/完成）——施工令 §一「已成单→链到单号」。没有单号的粒不给链：
