  const 链 = c.单号 ? `<a class="qtk mono" href="#/t/${encodeURIComponent(c.单号)}" title="进工单详情">${esc(c.单号)}</a>` : '';
  return `<div class="qrow${c.置灰 ? ' blocked' : ''}${终 ? ' fin' : ''}" title="${esc(c.提示)}">
      <span class="qs mono">${esc(c.批)}${c.序 ? '·' + c.序 : ''}</span>
