    const el = $('lv-step-t');
    if (!el) { clearInterval(window._lv); return; } // 已离开详情页
    el.textContent = step ? fmt(Date.now() - Date.parse(step)) : '--:--';
    const at = $('lv-all-t'); if (at && allIso) at.textContent = fmt(Date.now() - Date.parse(allIso));
    if (++n % 3 !== 0) return;
