    return `<div class="arow2 card r14${无会话 ? ' noagent' : ''}" id="agc-${esc(r.id)}" onclick="${go}" tabindex="0" role="button"
      aria-label="打开工单 ${esc(r.id)} 详情${无会话 ? '（在途但无执行会话）' : ''}"
