window.doSetup = async (目录) => {
  const r = await post('/api/setup', { 目录 });
  if (!r.ok) return toast(r.error || '建工作区失败');
  toast(`工作区就位：${r.root}`);
  _cfg = null;
  location.hash = '#/params';   // 直接落参数页——下一步就是注册项目仓库
