const KOPEN = 'studio.kchain.open'; // 展开态跨刷新保持：只存「制作人手动改过的那些单」
function kOpenMap() { try { return JSON.parse(localStorage.getItem(KOPEN) || '{}') || {}; } catch { return {}; } }
