// 技术策划入三表（施工令-028 范围 5 / 027 报备件）：H88 加了这个职能，色表却没跟上，
// 它的胶囊在流程/工单/在途各处一直是无色的（走 fnPill 的默认分支）。
const FN = { 策划: 'var(--fn-plan)', 技术策划: 'var(--fn-tplan)', 程序: 'var(--fn-code)', 美术: 'var(--fn-art)', QA: 'var(--fn-qa)', 装配: 'var(--fn-asm)' };
