    || `<p class="dim">收件箱空——没有需要你决定的${n('待投') ? `；<a href="#/board" style="color:var(--accent-ink)">待投区还有 ${n('待投')} 张可放行 →</a>` : ''}</p>`;
  // 池首投放建议已随拉取制退役（0.24.7 视图清仓）
  const lines = (jn.lines || []).slice(-5).reverse();
