function kChainHtml(链) {
  if (!链 || !链.length) return '<p class="dim">暂无关键汇报。</p>';
  const m = kOpenMap();
  // 顺手剪枝：只留还在当前卡片里的键，不然这个 map 会永远长下去
  const 活键 = {}; for (const c of 链) if (Object.prototype.hasOwnProperty.call(m, c.id)) 活键[c.id] = m[c.id];
