  return `已跑 ${tm(环节起时 || 领单时间, !!(p && p.超时))}${est ? ` · 预估 ${est}<span class="tmnote">（时长）</span>` : '<span class="tmnote">（无预估）</span>'}`;
}
// 百分比的出处（施工令-041 §四）：打点 → 「打点 3/7」；无打点 → 「阶段锚点（无打点）」。
// 悬浮说得出这个数怎么来的，才谈得上信任；两页共用这一句，口径不许各说各话。
function pctTitle(p) {
  const q = p || {};
