      <span class="sp"></span>
      <button class="btn accent h32" onclick="suspAsk('${esc(id)}',false,${子挂 ? 'true' : 'false'})">解挂 · 原位复活</button>
      <span class="sbwhy">派发 / 领单 / 质检 / 初检 / 核查 / 仲裁 / 巡检告警全部跳过本单；解挂后回到「${esc(d.state)}」原位继续被调度。${s.理由 ? '<br>理由：' + esc(s.理由) : ''}</span></div>`;
  }
  const ops = [];
