    // 不显示"加载中"：数据在后台取，旧版面保持到新版面整体就绪才一次换入（版面不因加载变动）
    const inner = await ROUTES[key]();
    // FLIP 捕捉：同在工单池时记住每张卡的旧位置，重渲染后滑到新位置（看得见"单子挪列"）
    const flipOld = {};
    if (key === 'board' && window._lastViewKey === 'board' && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
