/* ===== P16 Wiki（0.20）：三栏词条布局 · 双链 · 待审卡 ===== */
.wk-tools { display:flex; gap:10px; align-items:center; margin:18px 0 14px; }
.wk-grid { display:grid; grid-template-columns: 170px minmax(0,1fr) 210px; gap:16px; align-items:start; }
.wk-tree { border-right:0.5px solid var(--line); padding-right:12px; font-size:13px; }
.wk-cat { margin:0 0 8px; font-weight:600; }
.wk-it { margin:0 0 6px 16px; color:var(--ink2); cursor:pointer; }
.wk-it:hover { color:var(--ink); }
.wk-it.cur { color:var(--accent-ink); font-weight:600; }
/* 触点地板 ≥26px（W32 补巡 · 施工令-030）：词条内链原先只有一行文字高（~17px），
   在触屏与小鼠标上都难点。**保持 inline** 只加纵向 padding——行内元素的纵向 padding
   会撑大命中盒却不改变行盒高度，于是触点够了、正文行距一个像素没动（改 inline-block
   会把 wiki 正文的段落行距整体拉开，那就越界了）。 */
.wk-l { color:var(--accent-ink); cursor:pointer; padding:5px 2px; }
.wk-l:hover { text-decoration:underline; }
/* 裸引导链（决策台空态「想法池拍板 / 工单池待投区」）：同一条地板，同一种做法 */
.glink { color:var(--accent-ink); cursor:pointer; padding:5px 2px; }
.glink:hover { text-decoration:underline; }
.wk-l.ghost { opacity:.55; border-bottom:1px dashed var(--accent-ink); }
.wk-body { line-height:1.85; font-size:14px; }
.wk-body p { margin:0 0 12px; }
.wk-body ul { margin:0 0 12px 18px; padding:0; }
.wk-body li { margin-bottom:4px; }
.wk-h { margin:16px 0 8px; }
/* 正文表格（施工令-017）：窄屏自己横滚，绝不撑破三栏 */
.wk-tw { overflow-x:auto; margin:0 0 12px; }
.wk-t { width:100%; border-collapse:collapse; font-size:12.5px; line-height:1.6; }
.wk-t th { text-align:left; font-weight:600; color:var(--ink); border-bottom:1.5px solid var(--line); padding:6px 9px; white-space:nowrap; }
.wk-t td { border-bottom:0.5px solid var(--line); padding:6px 9px; vertical-align:top; color:var(--ink2); }
.wk-t td:first-child { color:var(--ink); white-space:nowrap; }
.wk-t tr:last-child td { border-bottom:none; }

