.hubcard.add:hover { border-color:var(--accent-ink); }

/* ===== P1 总览 ===== */
/* 统计横条（W32 补巡 · 施工令-030）：原先 height 写死 84px + 默认 nowrap，折行规则却只写在
   @media(max-width:680px) 里——860 断点根本吃不到。实数据七格（完成 79 / 归档 21 /
   实际工时 107.2h / 实耗预估 77% / 自修轮次 60 / 核查过不过 …）把这一行顶到 941px，
   整页跟着横向滚动；桩数据数字短，压根造不出这个宽度。
   所以这条不靠"试出来"保，靠"结构上不可能溢出"保：**默认就允许折行**，高度改由内容定。
   min-height 顶住原来的视觉高度——宽屏排得下一行时，渲染与改前逐像素相同。 */
.stat-strip { min-height:84px; border-radius:14px; display:flex; flex-wrap:wrap; align-items:center;
  row-gap:10px; padding:14px 32px; margin-top:24px; }
.stat-strip .grp { display:flex; flex-direction:column; justify-content:center; }
.stat-strip .grp .lbl { font-size:12px; color:var(--ink3); font-weight:500; }
.stat-strip .grp .num { font-family:var(--mono); font-size:22px; font-weight:500; line-height:1.3; }
.stat-strip .vdiv { width:1px; height:32px; background:var(--line); margin:0 22px; }
.stat-strip .spacer { flex:1; }
.stat-strip .grp.pool .num { font-size:18px; }
/* H81 常开单闸制：合闸=例外态，启动页顶部挂常驻红条（醒目，不埋角落） */
.gatealert { display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-top:20px;
  padding:14px 22px; border-radius:12px; background:var(--dangerbg);
  border:1px solid var(--danger); color:var(--danger); font-size:13.5px; }
.gatealert b { font-size:14.5px; font-weight:700; }
.gatealert .subnote { color:var(--danger); opacity:.85; }
.p1-grid { display:grid; grid-template-columns:700fr 628fr; gap:32px; margin-top:30px; align-items:start; }
.sec-h { display:flex; align-items:baseline; gap:14px; margin:0 0 16px; }
.inbox-row { height:68px; border-radius:12px; display:flex; align-items:center; padding:0 24px;
  margin-bottom:12px; cursor:pointer; }
.inbox-row:hover { border-color:var(--ink3); }
.inbox-row .rid { font-family:var(--mono); font-size:13px; color:var(--ink2); font-weight:500; width:64px; }
.inbox-row .rt { font-size:14px; font-weight:500; width:170px; }
.inbox-row .rnote { font-size:12px; color:var(--ink3); flex:1; }
/* 今日排程横幅（施工令-041 §二）：需你处理区下方一条横幅，一行话答三问。
   刻意比收件箱行矮、比它淡——它是**导航与态势**，不是待办；抢了收件箱的注意力就本末倒置。 */
.ovsched { display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:12px 20px; margin:4px 0 8px;
  cursor:pointer; font-size:12.5px; color:var(--ink2); border-radius:12px; }
.ovsched:hover { border-color:var(--accent); box-shadow:var(--shadow-sm); }
.ovsched .osk { font-size:11px; letter-spacing:.06em; color:var(--ink3); padding-right:4px;
  border-right:1px solid var(--line); margin-right:4px; }
.ovsched .ost b { font-family:var(--mono); font-size:13.5px; color:var(--ink); font-weight:700; }
.ovsched .ost.s b { color:var(--ok); }
.ovsched .osa { font-style:normal; color:var(--ink3); }
.suggest { border-radius:12px; padding:18px 24px; }
.logrow { display:flex; gap:16px; margin-bottom:18px; font-size:13px; }
.logrow time { font-family:var(--mono); font-size:12px; color:var(--ink3); width:52px; flex-shrink:0; }
.quota-card { border-radius:14px; padding:20px 24px; margin-top:24px; }
.qgrp { margin-top:16px; }
.qgrp .qhead { font-size:12px; font-weight:500; font-family:var(--mono); color:var(--ink2); display:flex; align-items:baseline; gap:8px; }
.qgrp .qstale { font-size:10px; color:var(--ink3); margin-left:auto; }
.qgrp .qrow2 { margin-top:8px; }
.qrow2 { display:flex; align-items:center; gap:14px; margin-top:16px; }
.qrow2 .qn { font-family:var(--mono); font-size:12px; color:var(--ink2); width:64px; }
.qbar { flex:1; height:6px; background:var(--line); border-radius:3px; overflow:hidden;
  box-shadow:inset 0 1px 1px var(--groove); } /* 量杆凹槽 */
.qbar i { display:block; height:100%; background:linear-gradient(90deg, var(--bar-from), var(--bar-to));
  border-radius:3px; transition:width .4s ease; } /* 凹槽+渐变：暖纸 2.0 定稿的量杆材质 */
.qbar i.hot { background:var(--danger); }
.qrow2 .qp { font-family:var(--mono); font-size:12px; font-weight:500; width:44px; text-align:right; }
.qsub { font-family:var(--mono); font-size:10px; color:var(--ink3); margin:2px 0 0 78px; }

/* ===== P2 工单池 ===== */
.gatebar2 { height:64px; border-radius:12px; display:flex; align-items:center; padding:0 24px; gap:20px; margin-top:24px; font-size:13px; }
.gatebar2 .gsec .glbl { display:block; font-size:11px; color:var(--ink3); font-weight:500; }
.gatebar2 .gv { display:flex; align-items:center; gap:8px; margin-top:2px; }
.gatebar2 .dot { width:7px; height:7px; border-radius:4px; background:var(--ok); display:inline-block; }
.gatebar2 .vdiv { width:1px; height:32px; background:var(--line); }
.gatebar2 .minibar { width:54px; height:6px; background:var(--line); border-radius:3px; overflow:hidden; display:inline-block; }
.gatebar2 .minibar i { display:block; height:100%; background:var(--ink3); }
.gatebar2 .minibar i.hot { background:var(--danger); }
.gatebar2 .backlog { margin-left:auto; }
.gatebar2 .backlog b { font-family:var(--mono); font-size:18px; font-weight:500; }
.board2 { display:flex; gap:12px; overflow-x:auto; margin-top:20px; align-items:flex-start; padding-bottom:8px;
  scrollbar-width:none; } /* 自带滑块藏起，由粘性 .hsync 代理 */
.board2::-webkit-scrollbar { display:none; }
/* 粘性代理滑块：列超视口时钉在窗口底边，滚到底自然回到栏目底边（用户原始诉求） */
.hsync { position:sticky; bottom:0; overflow-x:auto; overflow-y:hidden; height:14px; z-index:20;
  background:linear-gradient(to top, var(--paper) 70%, transparent); }
/* 列高过一屏：横向滑块贴在栏目底边，竖向滚到底才见（不悬浮在窗口下缘） */
.bcol2 { flex:0 0 160px; background:var(--sect); border-radius:14px; padding:16px 10px 12px; min-height:calc(100vh - 120px);
  box-shadow:inset 0 1px 0 var(--edge-hl); } /* 纸槽上缘受光 */
.bcol2.w168 { flex-basis:168px; } .bcol2.w128 { flex-basis:128px; }
.bcol2 h4 { margin:0 6px 14px; font-size:12.5px; display:flex; justify-content:space-between; align-items:center; }
.bcol2 h4 .cnt { font-family:var(--mono); font-size:12px; color:var(--ink3); font-weight:400; }
.bcol2.hot h4 { color:var(--danger); }
/* 施工令-005 第4条：改流式布局——胶囊排在标题块之后（不再 absolute），卡高随两行标题自适应。
   原 height:92px + 胶囊 absolute bottom 的组合，在 002 的两行截断落地后会让胶囊压住标题第二行。 */
.bcard2 { background:var(--card); border:1px solid var(--line); border-radius:10px; min-height:92px;
  padding:12px 14px; margin-bottom:12px; cursor:pointer; position:relative;
  display:flex; flex-direction:column; }
.bcard2:hover { border-color:var(--ink3); }
/* align-self:flex-start 让编号行回到"贴文字宽"（flex 项默认拉伸会撑满卡宽，撞上右上角
   absolute 的优先级角标）；max-width 是超长单号的兜底，宁可省略也不钻到角标底下 */
.bcard2 .cid { font-family:var(--mono); font-size:11px; color:var(--ink3);
  align-self:flex-start; max-width:calc(100% - 40px); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.bcard2 .cpri { position:absolute; top:12px; right:14px; font-family:var(--mono); font-size:11px; color:var(--ink3); }
.bcard2 .cpri.p0 { background:var(--dangerbg); color:var(--danger); font-size:10px; padding:1px 7px; border-radius:4px; top:11px; }
.bcard2 .ct { font-size:12px; font-weight:500; margin:5px 0 8px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
/* margin-top:auto 吃掉剩余空间把胶囊顶到卡底（短标题维持原观感）；.ct 的 margin-bottom
   是两行标题时的最小气口——flex 容器内不会外边距合并，所以两者叠加即最小间距。 */
.bcard2 > .pill { align-self:flex-start; margin-top:auto; flex:none; }
.newdraft { display:inline-flex; align-items:center; height:26px; padding:0 11px; border-radius:13px;
  border:1px solid var(--accent-ink); color:var(--accent-ink); font-size:11px; font-weight:500; background:var(--card); }

/* ===== 在途 · 执行时间轴（甘特并入） ===== */
.tlcard { padding:18px 24px; margin-bottom:14px; }
.tlflex { display:flex; gap:12px; margin-top:14px; }
.tlwhocol { flex-shrink:0; }
.tlwhocol .tlsp { height:20px; }
.tlwho { height:30px; display:flex; align-items:center; font-size:11px; font-weight:500; width:64px; color:var(--ink2); }
.tlscroll { flex:1; overflow-x:auto; min-width:0; padding-bottom:6px; }
.tlaxis { position:relative; height:20px; }
.tltick { position:absolute; top:2px; transform:translateX(-100%); font-family:var(--mono); font-size:10px; color:var(--ink3); }
.tllane { position:relative; height:22px; margin:4px 0; background:var(--sect); border-radius:6px;
  box-shadow:inset 0 1px 2px var(--groove-soft); } /* 轨道凹槽 */
.tlseg { position:absolute; top:3px; height:16px; border-radius:5px; opacity:.85; cursor:pointer;
  box-shadow:inset 0 1px 0 var(--edge-hl-soft); } /* 段条上缘受光，给"实体条"质感 */
/* 触点地板 ≥26px（施工令-044 F3）：段条本身是甘特刻度，高度=轨道几何（16px 内嵌 22px 轨道），
   不能为了好点就把它撑高——那会连带改泳道行高与堆叠层距（rowH/laneH 的 30px 节拍写在 app.js 里）。
   故走伪元素扩区：透明 ::after 只吃点击不参与布局，视觉一个像素不动。纵向 26px 居中展开=
   ±5px，仍在本行 30px 节拍之内，不会去抢上下泳道的点击。横向不扩：同一泳道里相邻两段挨得近，
   横向撑开会互相偷点击——段宽本身编码的是「跑了多久」，那才是它该保的语义。 */
.tlseg::after { content:''; position:absolute; left:0; right:0; top:50%; height:26px; transform:translateY(-50%); }
.tlseg:hover { opacity:1; }
.tlseglb { position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
  font-size:10px; font-style:normal; font-weight:600; color:rgba(0,0,0,.66); pointer-events:none; overflow:hidden; }
.tlseg.on { outline:1.5px solid var(--ink); }
.tlnow { position:absolute; top:0; width:0; border-left:1.5px dashed var(--danger); pointer-events:none; }

/* ===== P12 流程（施工令-022）：现在线 · 管线甘特 =====
   D43 的绝对定位阶段画布（.fl-node/.fl-e/.fl-lane…）整体退役，换成三列网格：管线 ｜ 现在（橙区）｜ 接下来。
   全部颜色走语义令牌（新增 --now/--nowtint 双主题），860px 断点整行竖排，永不横向溢出。 */
.fgtop { display:flex; align-items:baseline; gap:14px; flex-wrap:wrap; margin-top:22px; }
.fgtop .sp { flex:1; min-width:0; }
.nowh { color:var(--now); font-weight:700; }
.fgsum { font-size:12px; color:var(--ink3); white-space:nowrap; }
.fgsum b { font-family:var(--mono); color:var(--ink); font-size:12.5px; }
.fgsum b.s { color:var(--ok); }
.fgboard { position:relative; margin-top:12px; border:1px solid var(--line); border-radius:14px;
  background:var(--card); box-shadow:var(--shadow-sm); overflow:hidden; }
.fgcols { display:grid; grid-template-columns:200px 1fr 1.1fr; border-bottom:1px solid var(--line);
  color:var(--ink3); font-size:11px; letter-spacing:.06em; background:var(--sect); }
.fgcols > div { padding:8px 14px; min-width:0; }
.fglane { border-bottom:1px solid var(--line); }
.fglane:last-child { border-bottom:none; }
.fgrow { display:grid; grid-template-columns:200px 1fr 1.1fr; align-items:stretch; }
/* ---- 管线头 ---- */
.fghead { padding:12px 14px; border-right:1px solid var(--line); min-width:0; }
.fghead b { font-size:13.5px; }
.fghead .sub { color:var(--ink3); font-size:11px; margin-top:2px; overflow:hidden; text-overflow:ellipsis; }
.fghead .pct { font-family:var(--mono); color:var(--ok); font-size:12px; margin-top:6px; }
.fghead .lst { font-family:var(--mono); font-size:10px; font-weight:500; padding:1px 7px; margin-left:6px;
  border-radius:999px; background:var(--chip); color:var(--ink2); }
.fghead .lst.lag { background:var(--gatebg); color:var(--gatetx); border:1px solid var(--gateln); }
/* ---- 两个区：现在（橙）｜接下来 ---- */
.fgzone { padding:10px 12px; position:relative; min-width:0; }
.fgzone.now { background:var(--nowtint); border-left:2px solid var(--now); border-right:1px dashed var(--line); }
.fgidle { color:var(--ink3); font-size:11.5px; padding:14px 2px; text-align:center; }
.fgidle.q { text-align:left; padding:10px 2px; }
/* ---- 条：四型 ---- */
/* 过渡只给 box-shadow，**不给 border-color**：条的边色全是 var(--ok/--danger/--accent) 令牌，
   而带 transition 的属性在自定义属性被换掉（=切主题）时不重算，夜间会留着日间的绿边红边不放
   （2026-08-08 实机抓到：--ok 已是 #2FD6A0，.fgbar.sign 的边还钉在 #0D7A5F）。
   悬停反馈靠 box-shadow + 边色瞬时切换，观感不损，令牌正确性优先。 */
.fgbar { display:flex; align-items:center; gap:8px; margin:4px 0; padding:5px 10px; border-radius:7px;
  background:var(--chip); border:1px solid var(--line); cursor:pointer; min-width:0;
  transition:box-shadow .16s var(--ease-out); }
.fgbar:hover, .fgbar:focus-visible { border-color:var(--accent); box-shadow:var(--shadow-sm); outline:none; }
.fgbar .id { font-family:var(--mono); font-size:11px; color:var(--accent-ink); white-space:nowrap; }
.fgbar .t { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; flex:1 1 0; width:0; min-width:0; font-size:12.5px; } /* width:0 同病同修，见 .prow .pv 上方注释 */
.fgbar .st { font-size:10px; padding:1px 7px; border-radius:999px; white-space:nowrap; color:var(--ink2); background:var(--we); }
.fgbar .deps { font-family:var(--mono); font-size:10px; color:var(--ink3); white-space:nowrap; }
.fgbar .mile { font-size:10px; color:var(--now); white-space:nowrap; font-weight:600; }
/* 在做：实心 + 百分比（百分比是本视图唯一的实时数，给它 mono 与最强字重） */
.fgbar.doing { border-color:var(--accent); background:var(--accenttint); }
.fgbar.doing .pp { font-family:var(--mono); color:var(--ink); font-size:12.5px; font-weight:700; white-space:nowrap; }
/* 字号地板 10px（W32 补巡 · 施工令-030）：这个 % 号原是 9px，860 下已经糊成一团灰点。
   只抬到地板值，不动它在 .pp 里的从属关系（主角还是数字本身）。 */
.fgbar.doing .pp small { font-size:10px; font-weight:500; color:var(--ink3); margin-left:1px; }
.fgbar.doing .st { color:var(--accent-ink); background:transparent; border:1px solid var(--accent-ink); }
.fgbar.doing.nosess { border-style:dashed; }
.fgbar.doing.nosess .st { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
/* 排队：虚框 */
.fgbar.queue { background:transparent; border-style:dashed; }
.fgbar.queue .st { color:var(--ink3); background:transparent; border:1px solid var(--line); }
.fgbar.queue.ready { border-style:solid; border-color:var(--accent); box-shadow:0 0 0 2px var(--accent-glow); }
.fgbar.queue.ready .st { color:var(--accent-ink); border-color:var(--accent-ink); }
.fgbar.blocked .st { color:var(--danger); border-color:var(--danger); background:var(--dangerbg); }
/* 待判官接手（施工令-038）：委托待验收但判官会话还没起——闸门色，与 .doing.nosess 同源语义
   （"会话没起来"），虚框表明在排队。三个令牌两主题各有一份（:root 暖纸 / html[data-theme="glass"] 玻璃），
   实测 paper #7A5A1E on #FDF3E3、glass #E8B45A on 半透明琥珀，不写死色值。 */
.fgbar.queue.wait .st { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
/* 签字位：绿框常驻——制作人的活永远不许被别的条盖过去 */
.fgbar.sign { border-color:var(--ok); background:var(--okbg); }
.fgbar.sign .st { color:var(--ok); border:1px solid var(--okln); background:transparent; font-weight:700; }
/* 卡住：红 */
.fgbar.stuck { border-color:var(--danger); background:var(--dangerbg); }
.fgbar.stuck .st { color:var(--danger); border:1px solid var(--danger); background:transparent; font-weight:600; }
/* ---- 沉淀抽屉：折叠条（四类分计数）+ 展开列表 ---- */
.fgfold { display:flex; align-items:center; gap:4px; flex-wrap:wrap; margin-top:6px; padding-top:6px;
  border-top:1px dashed var(--line); font-size:11px; }
.fgfold .fgfk { color:var(--ink3); margin-right:2px; }
.fgfold .fgdot { color:var(--ink3); font-style:normal; opacity:.6; }
/* min-height 22 → 26（施工令-044 F3 触点地板）：四类分计数是真按钮（点开抽屉），
   胶囊自己就是命中盒，直接抬到地板高最直白——整条 .fgfold 随之高 4px，别处几何不动。 */
.fgcat { font:inherit; font-size:11px; color:var(--ink3); background:transparent; border:1px solid transparent;
  border-radius:999px; padding:1px 8px; cursor:pointer; min-height:26px; }
.fgcat b { font-family:var(--mono); font-weight:700; }
.fgcat:hover { color:var(--ink2); border-color:var(--line); }
.fgcat.on { color:var(--ink); border-color:var(--ink3); background:var(--we); }
.fgcat.susp.on { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
.fgcat.drop.on, .fgcat.over.on { color:var(--danger); border-color:var(--danger); background:var(--dangerbg); }
.fgdrawer { display:none; }
.fgdrawer.open { display:block; border-top:1px dashed var(--line); background:var(--sect); padding:8px 14px 12px; }
.fgdh { font-size:11px; color:var(--ink3); margin-bottom:6px; }
.fgdl { display:flex; flex-direction:column; gap:2px; }
/* 沉淀条一律置灰：它们已经不说话了，别跟活单抢注意力 */
.fgsi { display:flex; align-items:center; gap:10px; padding:3px 10px; border-radius:6px; text-decoration:none;
  color:var(--ink2); opacity:.62; filter:grayscale(.5); min-width:0; }
.fgsi:hover { opacity:1; filter:none; background:var(--we); }
.fgsi .id { font-family:var(--mono); font-size:10.5px; color:var(--ink3); white-space:nowrap; }
.fgsi .t { flex:1 1 0; width:0; min-width:0; font-size:12px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } /* width:0 同病同修，见 .prow .pv 上方注释 */
.fgsi .why { font-size:10px; color:var(--ink3); white-space:nowrap; }
.fgsi.susp .id { color:var(--gatetx); }
.fgsi.drop .why, .fgsi.over .why { color:var(--danger); }
/* ---- 计划粒（施工令-041 §一）：第六型条。与排队条同族（虚框），但更淡——
   它还没有工单号，视觉上必须一眼弱于任何一张真单，否则「计划」会冒充「在排队」。 */
.fgbar.queue.plan { border-color:var(--line); opacity:.86; }
.fgbar.queue.plan:hover, .fgbar.queue.plan:focus-visible { opacity:1; }
.fgbar.queue.plan .id { color:var(--ink3); }
.fgbar.queue.plan .t { color:var(--ink2); }
.fgbar .plb { font-size:10px; padding:1px 7px; border-radius:999px; white-space:nowrap;
  color:var(--ink3); background:transparent; border:1px dashed var(--ink3); }
/* 空态收敛（巡礼 F6）：整条管线无在做/无排队/无计划时只出一行，横跨现在+接下来两格 */
.fgzone.empty { grid-column:2 / 4; border-left:2px solid var(--line); }
/* 监制台维护队列行：非管线归属的计划粒（Q 队列） */
.fglane.qlane .fghead b { color:var(--ink2); }
.fglane.qlane .fghead .pct { color:var(--ink3); }
/* ---- 图例 ---- */
.fglegend { display:flex; gap:18px; color:var(--ink3); font-size:11px; margin-top:14px; flex-wrap:wrap; }
.fglegend i { display:inline-block; width:10px; height:10px; border-radius:3px; margin-right:5px; vertical-align:-1px; }
.fglegend i.lg-doing { background:var(--accent); }
.fglegend i.lg-queue { border:1px dashed var(--ink3); }
.fglegend i.lg-sign { background:var(--ok); }
.fglegend i.lg-stuck { background:var(--danger); }
.fglegend i.lg-plan { border:1px dashed var(--ink3); opacity:.6; }
/* 860px 以下：三列拆成竖排，每段自带小标题——横向滚动条一根都不许出现 */
@media (max-width:860px) {
  /* 折行后竖分隔线可能落在行首，成一根无所指的孤线——窄屏一律不出（原在 680 块，随折行上提到 860） */
  .stat-strip .vdiv { display:none; }
  /* 竖线一撤就得有别的东西替它分格，否则七格数字挤成一片 */
  .stat-strip { column-gap:22px; padding:14px 20px; }
  .fgcols { display:none; }
  .fgrow { grid-template-columns:1fr; }
  .fghead { border-right:none; border-bottom:1px solid var(--line); }
  .fgzone { border-right:none; }
  .fgzone::before { display:block; font-size:10px; letter-spacing:.06em; color:var(--ink3); margin-bottom:4px; }
  .fgzone.now::before { content:'◉ 现在在做'; color:var(--now); font-weight:700; }
  .fgzone.next::before { content:'→ 接下来（依赖序）'; }
  .fgzone.now { border-left:2px solid var(--now); }
  .fgsum { white-space:normal; }
}
@media (prefers-reduced-motion: reduce) { .fgbar, .fgsi { transition-duration:.01s; } }

/* ===== 在途细粒度进度（详情页顶卡）===== */
.livecard { margin-top:24px; padding:16px 20px 14px; }
.lv-top { display:flex; align-items:center; gap:10px; }
.lv-top .sp { flex:1; }
.lv-t { font-size:16px; font-weight:600; margin-left:16px; font-variant-numeric:tabular-nums; }
.lv-bar { display:flex; gap:6px; margin-top:14px; }
.lv-seg { flex:1; min-width:0; }
.lv-seg i { display:block; height:6px; border-radius:3px; background:var(--chip); }
.lv-seg span { display:block; font-size:10px; color:var(--ink3); margin-top:5px; text-align:center; }
.lv-seg.done i { background:var(--ok); opacity:.5; }
.lv-seg.done span { color:var(--ok); }
.lv-seg.cur i { background:var(--accent); animation:lvpulse 1.2s ease-in-out infinite; }
.lv-seg.cur span { color:var(--ink); font-weight:700; }
.lv-seg.wait i { background:var(--gateln); animation:lvpulse 2s ease-in-out infinite; }
.lv-tail { margin-top:10px; font-size:11px; color:var(--ink2); white-space:nowrap; overflow:hidden;
  direction:rtl; unicode-bidi:plaintext; text-align:left; } /* 只看得见尾部=最新输出 */
@keyframes lvpulse { 50% { opacity:.4; } }
@media (prefers-reduced-motion: reduce) { .lv-seg i { animation:none !important; } }

/* ===== P10 树形 · 已退役（施工令-028）=====
   .ttools / .tree2 / .trow2 族 / .twist2 / .tid2 / .tt2 / .kids / .mid / .prog / .acts /
   .mini3 / .accept-mini / .tree-note 全部随视图删除。下面三条 select 规则**不是树形的**——
   它们是全站原生下拉的暗色兜底（起草页职能/产出物/规模、模型选择器等 10 处仍在用），
   当年只是碰巧写在这一段里，退役时留下。 */
select { color-scheme:light; }
html[data-theme="glass"] select { color-scheme:dark; }
select option, select optgroup { background:var(--paper); color:var(--ink); }

/* ===== 子单表格（施工令-028：树形的「子单层级一览」迁入父单详情页）=====
   体例跟随详情页现有 .p8main 卡：整行可点、悬停有底、窄窗横向滚动而不是撑破页面。 */
.kidtbl-wrap { margin-top:10px; overflow-x:auto; }
.kidtbl { width:100%; border-collapse:collapse; font-size:12.5px; }
.kidtbl th { text-align:left; font-size:11px; font-weight:500; color:var(--ink3); padding:0 10px 6px 0; white-space:nowrap; border-bottom:1px solid var(--sect); }
.kidtbl td { padding:8px 10px 8px 0; border-bottom:1px solid var(--sect); vertical-align:middle; }
.kidtbl tbody tr { cursor:pointer; }
.kidtbl tbody tr:hover td { background:var(--sect); }
.kidtbl tbody tr:last-child td { border-bottom:none; }
.kidtbl .kid-id { font-size:11.5px; color:var(--ink3); white-space:nowrap; }
.kidtbl .kid-t { font-weight:500; max-width:320px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.kidtbl .kid-pool { font-size:11px; color:var(--ink3); white-space:nowrap; }
.kidtbl .kid-p { white-space:nowrap; }
.kidtbl .kid-p .bar { display:inline-block; width:72px; height:6px; background:var(--sect); border-radius:3px; overflow:hidden; vertical-align:middle; }
.kidtbl .kid-p .bar i { display:block; height:100%; background:var(--ok); }
.kidtbl .kid-p .pv { font-family:var(--mono); font-size:11px; color:var(--ink2); font-weight:500; margin-left:8px; }
@media (max-width:860px) { .kidtbl .kid-t { max-width:150px; } .kidtbl .kid-p .bar { width:44px; } }

/* ===== P3 在途 · 在跑卡（施工令-004 设计稿定稿）=====
   制作人 14:57 裁决：不点详情就要看见执行进度与百分比。百分比是这张卡的主角，
   分段条给「走到哪一段」，当前段内填充给「这一段走了多少」。色值一律走语义令牌。 */
.arow2 { border-radius:14px; padding:16px 20px; margin-bottom:14px; }
.arow2 .ar-row { display:flex; align-items:center; gap:16px; }
.arow2 .av { width:44px; height:44px; border-radius:10px; flex:none;
  display:flex; align-items:center; justify-content:center; font-size:13px; font-weight:600; }
/* width:0 加在这个**父 flex 项**上，不是加在带 nowrap 的 .at 上——.at 是块级子元素，
   给它 width:0 会把标题压成 0 宽整条消失（实测 728→0）；加在这里则 flex-grow 照常撑回。
   同病同修，原理见 .prow .pv 上方注释。 */
.arow2 .ar-id { min-width:0; flex:1 1 0; width:0; }
.arow2 .ar-idline { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.arow2 .aid { font-family:var(--mono); font-size:12px; color:var(--accent-ink); }
.arow2 .ar-who { font-size:11px; color:var(--ink3); }
.arow2 .at { font-size:14px; font-weight:600; margin-top:3px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.poolp.pool-claude { color:var(--pool-claude); }
.poolp.pool-codex { color:var(--pool-codex); }
/* 右列：百分比醒目，阶段名如实（判官阶段绝不冒充执行），计时贴在下面 */
.arow2 .ar-pct { flex:none; text-align:right; min-width:150px; }
.arow2 .pct { font-family:var(--mono); font-size:30px; font-weight:600; line-height:1;
  letter-spacing:-.02em; font-variant-numeric:tabular-nums; }
.arow2 .pct small { font-size:15px; color:var(--ink3); font-weight:400; }
.arow2 .ar-stage { font-size:11px; color:var(--ink2); margin-top:4px; }
.arow2 .ar-stage .dot { display:inline-block; width:6px; height:6px; border-radius:99px; background:var(--accent);
  margin-right:5px; vertical-align:1px; animation:arpulse 1.6s ease-out infinite; }
.arow2 .ar-stage.judge .dot { background:var(--fn-qa); }
.arow2 .ar-stage.warn { color:var(--danger); }
.arow2 .ar-stage.warn .dot { background:var(--danger); animation:none; }
.arow2 .ar-timer { font-family:var(--mono); font-size:11px; color:var(--ink3); margin-top:3px;
  font-variant-numeric:tabular-nums; }
.arow2 .ar-timer .over { color:var(--danger); }
/* 「（时长）」尾注（施工令-041 §四）：这一行是时长不是进度——页面上唯一的进度百分比在卡头 */
.arow2 .ar-timer .tmnote { font-family:var(--sans, inherit); color:var(--ink3); opacity:.75; margin-left:2px; }
/* 无会话态（建设性①，施工令-012）：在途但没有执行会话＝卡住了。三件套自证——
   降饱和 + 虚线边（不是实心在跑卡）+ 计时行直写「已等 N 分钟未起会话」，不用读小字分辨。 */
.arow2.noagent { border:1px dashed var(--ink3); background:var(--we); filter:saturate(.35); }
.arow2.noagent .ar-stage.nosess { color:var(--ink3); }
.arow2.noagent .ar-stage.nosess .dot { background:var(--ink3); animation:none; }
.arow2.noagent .ar-timer.nosess { color:var(--ink2); font-weight:600; }
@keyframes arpulse { 0% { opacity:1; } 50% { opacity:.35; } 100% { opacity:1; } }
/* 阶段分段条：填满=已过 · 当前=段内进度条（右缘扫光示意「活着」）· 未到=灰槽 */
.segbar { display:flex; gap:6px; margin-top:14px; }
.segbar .seg { flex:1 1 0; width:0; min-width:0; } /* width:0 加在父 flex 项：阶段名 span 是块级子元素带 nowrap，同 .arow2 .ar-id 的处理 */
.segbar .seg i { display:block; height:5px; border-radius:99px; background:var(--chip); position:relative; overflow:hidden; }
.segbar .seg.done i { background:var(--ok); }
.segbar .seg.cur i em { position:absolute; inset:0; width:var(--fill,0%); border-radius:99px;
  background:var(--accent); box-shadow:0 0 10px var(--accent-glow); transition:width .4s var(--ease-out); }
.segbar .seg.cur i em::after { content:''; position:absolute; top:0; right:0; width:14px; height:100%;
  background:linear-gradient(90deg, transparent, var(--sweep)); animation:arsweep 1.8s ease-out infinite; }
.segbar .seg.cur.judge i em { background:var(--fn-qa); box-shadow:none; }
.segbar .seg.cur.warn i em { background:var(--danger); box-shadow:0 0 10px var(--glow-live); }
.segbar .seg.cur.warn i em::after { animation:none; opacity:0; } /* 超时：填满转红、停扫光 */
.segbar .seg span { display:block; font-size:10px; color:var(--ink3); margin-top:5px; text-align:center;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.segbar .seg.cur span { color:var(--ink); font-weight:600; }
.segbar .seg.done span { color:var(--ok); }
@keyframes arsweep { 0% { opacity:0; } 50% { opacity:1; } 100% { opacity:0; } }
@media (prefers-reduced-motion: reduce) {
  .arow2 .ar-stage .dot { animation:none; }
  .segbar .seg.cur i em { transition:none; }
  .segbar .seg.cur i em::after { animation:none; opacity:0; }
}
/* 总览在跑摘要（施工令-004 第 4 条）：规格从简，一行一单——百分比 + 阶段名 */
.ovrun { padding:6px 14px; margin-bottom:12px; }
.ovrun-row { display:flex; align-items:center; gap:10px; padding:8px 2px; text-decoration:none; color:inherit;
  border-bottom:1px solid var(--line); }
.ovrun-row:last-child { border-bottom:0; }
.ovrun-row .rid { font-size:11px; color:var(--ink3); flex:none; }
.ovrun-row .rt { font-size:12.5px; color:var(--ink2); flex:1 1 0; width:0; min-width:0;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } /* width:0 同病同修，见 .prow .pv 上方注释 */
.ovrun-row .pct { font-size:14px; font-weight:600; color:var(--ink); font-variant-numeric:tabular-nums; }
.ovrun-row .pct.over { color:var(--danger); }
.ovrun-row .st { font-size:11px; color:var(--ink3); flex:none; }
.ovrun-row:hover .rt { color:var(--ink); }
.ovrun-row:focus-visible { outline:2px solid var(--accent); outline-offset:2px; border-radius:6px; }

/* 尾行：最近一行输出，mono 弱化——正文不是重点，进度才是 */
.arow2 .ar-tail { font-family:var(--mono); font-size:11px; color:var(--ink3); margin-top:12px;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.arow2 .ar-tail b { color:var(--ink2); font-weight:400; }
.logcard { border-radius:14px; padding:18px 24px; }

/* ===== P4 决策台 ===== */
.dtabs { display:flex; align-items:center; gap:22px; margin-top:26px; }
.dtabs .tab { font-size:16px; color:var(--ink3); cursor:pointer; padding-bottom:8px; border-bottom:2px solid transparent; display:flex; gap:8px; align-items:center; }
.dtabs .tab.active { color:var(--ink); font-weight:700; border-bottom-color:var(--ink); }
.dtabs .badge { display:inline-flex; align-items:center; justify-content:center; min-width:22px; height:18px;
  padding:0 6px; border-radius:9px; background:var(--dangerbg); color:var(--danger); font-family:var(--mono); font-size:11px; }
.dtabs .backlog2 { margin-left:auto; font-family:var(--mono); font-size:12px; color:var(--ink3); font-weight:500; }
.dgrid { display:grid; grid-template-columns:minmax(0,880fr) minmax(0,460fr); gap:20px; margin-top:18px; align-items:start; }
.dmain { border-radius:16px; padding:26px 28px; min-width:0; }
.dmain h2 { margin:0 0 16px; font-size:20px; }
.dpanes { display:grid; grid-template-columns:minmax(0,530fr) minmax(0,270fr); gap:22px; margin-top:18px; }
.dpane { background:var(--sect); border-radius:12px; padding:18px 22px; min-height:300px; }
.dpane .ph { font-size:11px; color:var(--ink3); font-weight:500; margin-bottom:12px; }
.dpane .doc-line { font-size:12.5px; color:var(--ink2); margin:10px 0; }
.dpane .doc-line.hd { font-size:14px; color:var(--ink); font-weight:700; }
.dpane .taste { color:var(--danger); font-size:11px; font-weight:500; margin-top:18px; }
.dsign { display:flex; align-items:center; gap:16px; background:var(--okbg); border:1px solid var(--okln);
  border-radius:12px; padding:10px 20px; margin-top:20px; font-size:13px; color:var(--ink2); }
.dsign .btns { margin-left:auto; display:flex; gap:14px; }
.dside { border-radius:16px; padding:22px 24px; margin-bottom:20px; min-width:0; }
.dside .qitem { background:var(--sect); border-radius:12px; padding:12px 20px; margin-top:14px; cursor:pointer; }
.dside .qitem:hover { outline:1px solid var(--ink3); }
.dside .qitem .qi { font-family:var(--mono); font-size:12px; font-weight:500; }
.dside .qitem .qn2 { font-size:11px; color:var(--ink2); margin-top:3px; }

/* ===== P5 风格库 ===== */
.p5grid { display:grid; grid-template-columns:680fr 636fr; gap:40px; margin-top:24px; align-items:start; }
.axcard { border-radius:12px; padding:16px 26px 14px; margin-bottom:16px; }
.axcard h4 { margin:0 0 8px; font-size:14px; }
.axcard p { margin:0 0 10px; font-size:12.5px; color:var(--ink2); }
.addbar { border-radius:12px; height:56px; display:flex; align-items:center; gap:16px; padding:0 26px; cursor:pointer; }
.addbar:hover { border-color:var(--ink3); }
.addbar .a1 { color:var(--accent-ink); font-size:13px; font-weight:500; }
.artgrid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
.artcard { border-radius:12px; padding:16px; }
.artcard .thumb { height:118px; border-radius:8px; position:relative; overflow:hidden; background:var(--sect);
  box-shadow:inset 0 1px 2px var(--groove-soft); }
.artcard .thumb img { width:100%; height:100%; object-fit:cover; display:block; }
.artcard .thumb.ftype { display:flex; align-items:center; justify-content:center; font-size:18px; color:var(--ink3); letter-spacing:.1em; }
.artcard .thumb .pill { position:absolute; top:14px; left:14px; background:var(--card); }
/* 条目元信息行 + 移出按钮（精选制反向闸） */
.axmeta { display:flex; align-items:center; gap:10px; margin-top:4px; }
.axmeta .axdate { font-size:10px; color:var(--ink3); }
.axdel { margin-left:auto; width:22px; height:22px; border-radius:11px; color:var(--ink3); font-size:14px;
  display:inline-flex; align-items:center; justify-content:center; transition:color 150ms var(--ease-out), background 150ms var(--ease-out); }
.axdel:hover { color:var(--danger); background:var(--dangerbg); }
.artcard .ac .axdel { float:right; }
/* 入库弹窗遮罩 */
.mwrap .mback { position:fixed; inset:0; background:var(--mask); z-index:44; }
.mwrap .modal2 { z-index:45; width:460px; padding:24px 28px; }
.artcard .an { font-size:13px; font-weight:500; margin-top:12px; }
.artcard .ac { font-family:var(--mono); font-size:10px; color:var(--ink3); margin-top:2px; }
.emptycard { background:var(--paper); border:1px solid var(--line); border-radius:12px; padding:20px 26px; margin-top:20px; }
.emptycard h5 { margin:0 0 8px; font-size:13px; color:var(--ink2); }
.emptycard p { margin:0; font-size:12px; color:var(--ink3); }
/* 空态里的出路按钮：文案让点什么，钮就得在卡里（施工令-006 死胡同案） */
.emptycard .emptyact { margin-top:14px; }

/* ===== P13 消耗报表 ===== */
.rp-grid { display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-top:20px; align-items:start; }
/* grid 子项默认 min-width:auto —— 轨道会被"最宽的那个不可断内容"顶开，于是两列网格
   在 860 下把整页撑出横向滚动条（W32 补巡 · 施工令-030）。min-width:0 把这条地板拆掉，
   宽内容改由各自的 .rp-scroll 在容器内滚，页面文档宽恒等于视口宽。 */
.rp-grid > * { min-width:0; }
.rp-card { padding:18px 24px; margin-bottom:16px; }
.rp-card h4 { margin:0 0 12px; font-size:14px; }
.rp-t { width:100%; border-collapse:collapse; font-size:12px; }
.rp-t th { text-align:left; font-size:10.5px; color:var(--ink3); font-weight:500; padding:4px 10px 6px 0; border-bottom:1px solid var(--sect); }
.rp-t td { padding:6px 10px 6px 0; border-bottom:1px solid var(--sect); font-family:var(--mono); font-size:11.5px; }
.rp-t td:first-child { color:var(--ink2); }
.rp-t tr:last-child td { border-bottom:none; }
.rp-t tr:hover td { background:var(--we); }
/* 宽表横滚（W32 补巡 · 施工令-030）：工单明细 8 列在 860 下把**页面**撑出横向滚动条，
   整个视图跟着左右晃。改成让表格在自己的容器里滚——页面文档宽恒等于视口宽。
   min-width:0 是 flex/grid 子项里 overflow 生效的前提（不给的话子项按内容撑，照样溢出）。 */
.rp-scroll { overflow-x:auto; min-width:0; }
.rp-days { display:flex; gap:8px; align-items:flex-end; min-height:80px; padding-top:6px; overflow-x:auto; }
.rp-day { display:flex; flex-direction:column; align-items:center; gap:4px; }
.rp-day i { display:block; width:18px; border-radius:4px 4px 0 0; background:linear-gradient(180deg, var(--bar-to), var(--bar-from)); }
.rp-day span { font-family:var(--mono); font-size:10px; color:var(--ink3); }

/* ===== P6 参数与额度 ===== */
.p6grid { display:grid; grid-template-columns:680fr 636fr; gap:40px; margin-top:24px; align-items:start; }
/* 施工令-012 / 巡礼 P2-2：原 height:88px 是定高，说明文字一换行就越过下边界压到下一张卡
   （实测下溢 14–51px，而卡间距只有 14px）。改 min-height 自适应；说明文字再加两行截断兜底，
   悬停 title 看全文。等宽的 .mono 说明（兼容池端点 / 手机访问地址）不截断——那两行本身就是要看全的。 */
.paramcard { border-radius:12px; min-height:88px; padding:18px 26px; margin-bottom:14px; position:relative; }
.paramcard h4 { margin:0 0 6px; font-size:14px; }
.paramcard p { margin:0; font-size:12px; color:var(--ink3); }
.paramcard p.pmeta:not(.mono) { display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; line-clamp:2;
  overflow:hidden; word-break:break-word; line-height:1.45; }
/* 定位控件（步进器/开关）宽度固定，给同高的文字让出右槽，换行后不再钻到控件底下。
   槽宽取 min()：卡被挤窄时（P3-5 那类轨道塌缩）让位给文字，绝不把正文压成一字一行。 */
.paramcard:has(.stepper) h4, .paramcard:has(.stepper) p.pmeta { padding-right:min(140px, 38%); }
.paramcard:has(.egtoggle) h4, .paramcard:has(.egtoggle) p.pmeta { padding-right:min(130px, 38%); }
.paramcard .stepper { position:absolute; right:26px; top:26px; display:flex; align-items:center; }
.paramcard .stepper button { width:36px; height:36px; border-radius:9px; border:1px solid var(--line);
  background:var(--card); color:var(--ink3); font-size:15px; }
.paramcard .stepper button:hover { border-color:var(--ink3); color:var(--ink); }
.paramcard .stepper .val { width:60px; text-align:center; font-family:var(--mono); font-size:22px; font-weight:500; }
.paramcard .fixed { position:absolute; right:26px; top:50%; transform:translateY(-50%); font-size:15px; color:var(--ink2); font-weight:500; }
.paramcard .egtoggle { position:absolute; right:26px; top:26px; display:flex; gap:8px; }
.paramcard .egbtn { width:56px; height:36px; border-radius:18px; border:1px solid var(--line);
  background:var(--card); color:var(--ink2); font-size:13px; }
.paramcard .egbtn:hover { border-color:var(--ink3); color:var(--ink); }
.paramcard .egbtn.on { background:var(--ink); color:var(--paper); border-color:var(--ink); font-weight:500; }
/* 执行器（D30）：状态灯 + 环境探针 */
.dot { display:inline-block; width:10px; height:10px; border-radius:5px; margin-right:8px; background:var(--ink3); vertical-align:baseline; }
.dot.on { background:var(--ok); }
.dot.err { background:var(--danger); }
.dot.warn { background:var(--warn); } /* 黄=能力受限（降级）；施工令-034 起指语义令牌 --warn，不再借闸门色 */
/* 卡片内单行（凭据卡 / 向导候选目录）——施工令-027：
   此前 .rowline 全站没有一条 CSS 规则，是裸 <p>：行距随浏览器默认走、按钮吊在文字基线上、
   两行之间没有分隔。现按 .envcard .envrow 的同款体例收拾——一行 flex、竖直居中、
   说明吃掉剩余宽度把按钮顶到右缘，行与行之间一条细线。 */
.rowline { display:flex; align-items:center; gap:10px; margin:0; padding:8px 0; font-size:13px;
  border-bottom:1px solid var(--sect); }
.rowline:last-of-type { border-bottom:none; }
.rowline .dot { margin-right:0; flex-shrink:0; }
.rowline .rl-name { font-weight:500; min-width:60px; flex-shrink:0; }
.rowline .rl-note { color:var(--ink3); flex:1; min-width:0; }
.rowline .btn, .rowline code, .rowline .pill { flex-shrink:0; }
/* 窄幅（<860）说明会换行到第二行，第一行只剩 圆点+名称+按钮——不推一把按钮就吊在名字屁股后面 */
.rowline .rl-push { margin-left:auto; }
.rowline code { flex:1 1 0; width:0; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } /* width:0 同病同修（向导候选目录是长路径重灾区），见 .prow .pv 上方注释 */
.dotlegend { display:flex; align-items:center; flex-wrap:wrap; gap:4px 14px; }
.dotlegend .dot { margin-right:4px; }
@media (max-width:860px) {
  .rowline { flex-wrap:wrap; }
  .rowline .rl-note { flex:1 0 100%; order:3; }
}
.warnc { color:var(--warn); }
.pill.warn { background:var(--warnbg); color:var(--warn); }

/* ===== 凭据卡（施工令-034 设计稿定稿）=====
   三行一个体例：状态点 · 名称(定宽列) · 类型胶囊 · 状态一句话(带次要小字) · 右侧动作组。
   订阅行与托管行此前是两套长相（一个 圆点+粗名+说明，一个 池名胶囊+等宽指纹），
   同一张卡里读起来像两张表；现在共用 .credrow，差别只剩胶囊里那两个字。
   边距按施工令硬指标：卡内边距 ≥20px、行纵向 padding ≥10px、分隔线不贴边（left/right 各留 2px）。 */
.credcard { padding:20px 24px; }
.credcard .cred-sub { margin:0 0 14px; font-size:12px; color:var(--ink3); line-height:1.55; }
.credrow { display:flex; align-items:center; gap:12px; margin:0; padding:11px 2px; font-size:13px;
  border-top:1px solid var(--line); }
.credrow:first-of-type { border-top:none; }
.credrow .dot { width:8px; height:8px; border-radius:50%; margin-right:0; flex:none; }
/* 名称定宽 86px：三行的类型胶囊因此对齐成一列，眼睛一趟扫下来不用重新找基准 */
.credrow .cr-name { font-weight:600; width:86px; flex:none; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.credrow .cr-kind { font-size:11px; color:var(--ink3); background:var(--chip); border-radius:99px;
  padding:1px 8px; flex:none; white-space:nowrap; }
/* width:0 不是笔误，是这一条的命门（自测抓到）：状态句要单行省略号就得 white-space:nowrap，
   而 nowrap 让这个 flex-grow 项的 min-content 等于整句话的长度，再顺着 flex 容器一路顶到
   .p6grid 的列宽上——参数页右列被撑到 807px，整页横向出滚动条。min-width:0 挡不住这条路
   （它管的是自动最小尺寸），显式 width:0 才能把内在贡献真正归零；flex-grow 照常把它撑回可用宽度。
   实测：卡片 min-content 807px → 413px，栅格回到 259/490，省略号照常工作。 */
.credrow .cr-stat { color:var(--ink); opacity:.85; flex:1 1 0; width:0; min-width:0;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.credrow .cr-stat small { color:var(--ink3); }
.credrow .cr-act { display:flex; align-items:center; gap:8px; margin-left:auto; flex:none; }
.credcard .cred-foot { display:flex; align-items:center; gap:10px; margin:0; padding-top:14px; margin-top:2px;
  border-top:1px solid var(--line); flex-wrap:wrap; }
.credcard .cred-foot .grow { flex:1; }
/* 状态图例：收进右下角，悬停才展开。tooltip 自绘（原生 title 在 Electron 壳里样式不可控、
   延迟一秒才出，四档色值这种"要对着看"的信息等不起），纯 CSS，无 JS 无原生件。 */
.credleg { position:relative; font-size:11px; color:var(--ink3); cursor:default; }
.credleg .credtip { display:none; position:absolute; right:0; bottom:calc(100% + 8px); z-index:20;
  background:var(--frost); backdrop-filter:blur(var(--frost-blur)) saturate(1.15);
  -webkit-backdrop-filter:blur(var(--frost-blur)) saturate(1.15);
  border:1px solid var(--line); border-radius:10px; padding:10px 14px; font-size:12px; color:var(--ink);
  box-shadow:var(--shadow-lg); white-space:nowrap; line-height:1.9; }
.credleg:hover .credtip, .credleg:focus-visible .credtip { display:block; }
.credleg .credtip i { font-style:normal; display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:7px; }
.credleg .credtip .lg-ok { background:var(--ok); } .credleg .credtip .lg-warn { background:var(--warn); }
.credleg .credtip .lg-err { background:var(--danger); } .credleg .credtip .lg-unk { background:var(--ink3); }
.credcard .cred-empty { margin:0; padding:11px 2px; font-size:13px; color:var(--ink3); border-top:1px solid var(--line); }
/* 窄幅：状态句让位换行到第二行，第一行保住 点+名+胶囊+按钮组，按钮不吊在名字屁股后面 */
@media (max-width:860px) {
  .credrow { flex-wrap:wrap; }
  .credrow .cr-stat { flex:1 0 100%; order:5; white-space:normal; }
  .credrow .cr-act { order:4; }
}
/* 全链路自检分组 */
.eg-head { display:flex; align-items:center; margin-bottom:6px; }
.envgrp { margin-top:12px; }
.envgrp .eg-t { font-size:11px; font-weight:500; color:var(--ink3); padding-bottom:4px; border-bottom:1px solid var(--sect); }
.envgrp .ek { width:110px; flex-shrink:0; }
.paramcard .runbtn { position:absolute; right:26px; top:50%; transform:translateY(-50%); }
.envcard { border-radius:12px; padding:18px 26px 20px; margin-bottom:16px; }
.envcard .envrow { display:flex; align-items:center; gap:10px; padding:7px 0; font-size:13px; border-bottom:1px solid var(--sect); }
.envcard .envrow:last-of-type { border-bottom:none; }
.envcard .ek { width:56px; font-weight:500; }
.envcard .ev { flex:1 1 0; width:0; min-width:0; font-family:var(--mono); font-size:11.5px; color:var(--ink2); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } /* width:0 同病同修，见 .prow .pv 上方注释 */
.envcard .ev.err { color:var(--danger); }
.poolcard { border-radius:12px; padding:18px 26px 22px; margin-bottom:16px; }
.poolcard .pr { display:flex; align-items:baseline; gap:16px; }
.poolcard .pr h4 { margin:0; font-size:14px; }
.poolcard .pr .pstat { font-size:11px; font-weight:500; }
.poolcard .meta { font-family:var(--mono); font-size:11px; color:var(--ink3); margin:6px 0 12px; }
.poolcard .pbar { height:8px; background:var(--sect); border-radius:4px; overflow:hidden;
  box-shadow:inset 0 1px 1px var(--groove); }
.poolcard .pbar i { display:block; height:100%; background:linear-gradient(90deg, var(--bar-from), var(--bar-to)); }
.poolcard .pbar i.hot { background:var(--danger); }
/* 一窗一行（施工令-006）：读数、量杆、管它的那根杆同处一行，跨窗口不并排 */
.poolcard .qline { display:flex; align-items:center; gap:10px; margin-top:10px; }
.poolcard .qline .ql { width:20px; font-size:11px; color:var(--ink3); flex-shrink:0; }
.poolcard .qline .qv { width:40px; font-size:12px; color:var(--ink2); flex-shrink:0; }
.poolcard .qline .qv.err { color:var(--danger); }
.poolcard .qline .pbar { flex:1; min-width:60px; }
.poolcard .qline .qgate { font-family:var(--mono); font-size:10.5px; color:var(--ink3); flex-shrink:0; }
.poolcard .qline .qwin { color:var(--ink3); opacity:.75; }
/* 沟通护城河提示：中性告知（这是设定内的行为，不是故障），走警示色不走危险红 */
.poolcard .moat { margin-top:12px; font-size:11.5px; line-height:1.5; padding:7px 12px; border-radius:8px;
  background:var(--gatebg); color:var(--gatetx); border:1px solid var(--gateln); cursor:help; }
/* 编制行（H85 补章起：项管页只读编制快照，每职能一行）：左缘 4px 职能色书脊条（暖纸 2.0），颜色由行内 var 注入。
   池序可能挂多池（codex→claude→…），行高改 min-height + 允许换行；右侧给状态 pill 留出净空不压字。 */
.teamrow { border-radius:12px; min-height:56px; display:flex; align-items:center; flex-wrap:wrap; gap:8px 12px;
  padding:10px 132px 10px 24px; margin-bottom:12px; position:relative; border-left:4px solid var(--line); }
.teamrow b { font-size:13px; }
.teamrow .stpill { position:absolute; right:20px; top:50%; transform:translateY(-50%); }

/* ===== P7 起草 ===== */
.p7grid { display:grid; grid-template-columns:470fr 870fr; gap:20px; margin-top:24px; align-items:start; }
.formcard { border-radius:16px; padding:24px 26px; }
.formcard h3 { margin:0 0 20px; font-size:15px; }
.f-field { margin-bottom:16px; }
.f-field label { display:block; font-size:11px; color:var(--ink3); font-weight:500; margin-bottom:6px; }
.f-field input, .f-field select { width:100%; height:40px; }
.f-2col { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
.f-sec { margin-bottom:20px; }
.f-sec .sh { font-size:12.5px; font-weight:700; margin-bottom:8px; }
.f-sec textarea { width:100%; resize:vertical; font-size:12.5px; line-height:1.6; }
.p7foot { display:flex; justify-content:flex-end; gap:16px; margin-top:8px; }

/* ===== P8 详情 ===== */
.p8grid { display:grid; grid-template-columns:880fr 460fr; gap:20px; margin-top:24px; align-items:start; }
.p8main { border-radius:16px; padding:24px 28px; margin-bottom:16px; }
.p8main h2 { margin:0 0 14px; font-size:20px; }
.chipsrow { display:flex; gap:8px; flex-wrap:wrap; }
.chain { margin-top:18px; }
.chain .clbl { font-size:11px; color:var(--ink3); font-weight:500; margin-bottom:10px; }
.chain .crow { display:flex; gap:20px; margin-bottom:12px; font-size:13px; align-items:baseline; }
.chain .crow .ck { font-size:11px; color:var(--ink3); font-weight:500; width:66px; flex-shrink:0; }
.chain .crow .cv { font-family:var(--mono); font-weight:500; }
.doc2 { font-size:12.5px; color:var(--ink2); }
.doc2 h1, .doc2 h2, .doc2 h3 { font-size:14px; color:var(--ink); margin:16px 0 8px; }
.doc2 p, .doc2 ul { margin:8px 0; }
.rside { border-radius:16px; padding:22px 26px; margin-bottom:20px; }
.rside h3 { margin:0 0 6px; font-size:15px; }
/* 回执轮页签（施工令-034）：返修/自修把每一轮追加进同一个回执文件，此前详情页只渲染最新一轮，
   旧轮内容在界面上根本不存在（要看只能去翻 .md）。现在每轮一个页签，默认落最新轮。
   单轮回执不出这套壳——只有一轮时 .rtabs 压根不渲染，那条动线一个像素没变。 */
.rtabs { display:flex; flex-wrap:wrap; gap:6px; margin:10px 0 2px; }
.rtab { padding:4px 12px; border-radius:99px; border:1px solid var(--line); background:transparent;
  color:var(--ink3); font-size:11.5px; font-weight:500; cursor:pointer; white-space:nowrap;
  transition:color 140ms var(--ease-out), border-color 140ms var(--ease-out), background 140ms var(--ease-out); }
.rtab:hover { color:var(--ink); border-color:var(--ink3); }
.rtab.on { background:var(--ink); color:var(--paper); border-color:var(--ink); }
.rtab:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.rtab-pane { display:none; }
.rtab-pane.on { display:block; }
@media (prefers-reduced-motion: reduce) { .rtab { transition:none; } }
.rsec { background:var(--sect); border-radius:12px; padding:12px 22px; margin-top:14px; }
.rsec .rl { font-size:11px; color:var(--ink3); font-weight:500; }
.rsec .rv { font-size:12.5px; font-weight:500; margin-top:3px; }
.oprow2 { border:1px solid var(--line); border-radius:10px; height:54px; display:flex; align-items:center;
  gap:14px; padding:0 22px; margin-top:14px; cursor:pointer; background:var(--card); width:100%; text-align:left; }
.oprow2:hover { border-color:var(--ink3); }
.oprow2 b { font-size:13px; }
.oprow2 span { font-size:11px; color:var(--ink3); }

/* ===== P9b 排期弹窗 ===== */
.modal-mask { position:fixed; inset:0; background:var(--mask-strong); z-index:40; }
.modal2 { position:fixed; z-index:45; top:50%; left:50%; transform:translate(-50%,-50%);
  width:560px; max-height:88vh; overflow-y:auto; background:var(--frost); border:1px solid var(--line);
  backdrop-filter:blur(var(--frost-blur)) saturate(1.15); -webkit-backdrop-filter:blur(var(--frost-blur)) saturate(1.15);
  border-radius:20px; padding:28px 32px; box-shadow:var(--shadow-lg); } /* 悬浮层磨砂第二处：弹窗（暖纸 2.0） */
.modal2 h3 { margin:0 0 22px; font-size:18px; display:flex; justify-content:space-between; }
.modal2 h3 .x { color:var(--ink3); cursor:pointer; font-size:20px; font-weight:400; }
.modal2 .note { font-size:10.5px; color:var(--ink3); margin-top:14px; }
.modal2 .mfoot { display:flex; align-items:center; margin-top:26px; }
.modal2 .mfoot .rgt2 { margin-left:auto; display:flex; gap:12px; }

/* ===== P13 遥控传令板（0.17.10） ===== */
.rl-wrap { max-width:860px; margin:24px auto 0; display:flex; flex-direction:column; min-height:calc(100vh - 190px); }
.rl-head { display:flex; flex-direction:column; gap:4px; margin-bottom:14px; }
.rl-list { flex:1; min-height:52vh; overflow-y:auto; padding:18px; display:flex; flex-direction:column; gap:14px; }
.rl-msg { max-width:82%; }
.rl-msg.me { align-self:flex-end; text-align:right; }
.rl-msg.ai { align-self:flex-start; }
.rl-meta { font-size:10px; color:var(--ink3); margin-bottom:4px; }
.rl-body { display:inline-block; text-align:left; padding:10px 14px; border-radius:14px; font-size:13.5px; line-height:1.6; white-space:pre-wrap; word-break:break-word; }
.rl-msg.me .rl-body { background:var(--accent); color:var(--on-accent); border-bottom-right-radius:4px; }
.rl-msg.ai .rl-body { background:var(--sect); border:1px solid var(--line); border-bottom-left-radius:4px; }
.rl-input { display:flex; gap:10px; margin-top:14px; }
.rl-input textarea { flex:1; height:72px; resize:none; border-radius:14px; padding:12px 14px; }

/* ===== 移动端适配（0.17.10）：手机驾驶舱——总览/决策台/详情/遥控/启动页优先 ===== */
@media (max-width: 680px) {
  body { padding:0 12px 40px; }
  .topbar { flex-direction:column; align-items:flex-start; gap:10px; }
  .topbar .tright { width:100%; display:flex; }
  .topbar .tright input { flex:1; min-width:0; }
  nav.snav { overflow-x:auto; white-space:nowrap; -webkit-overflow-scrolling:touch;
    scrollbar-width:none; display:flex; flex-wrap:nowrap; max-width:100vw; }
  nav.snav::-webkit-scrollbar { display:none; }
  .hubgrid { grid-template-columns:1fr !important; }
  .p7grid, .p8grid { grid-template-columns:1fr !important; display:block; }
  .p8grid > div { width:100%; }
  .p8main, .rside, .formcard, .livecard { margin-top:14px; }
  .dpanes { flex-direction:column; }
  .board2 { overflow-x:auto; -webkit-overflow-scrolling:touch; }
  .oprow2 { min-height:44px; }
  .btn.h32 { min-height:38px; }
  .prow { flex-wrap:wrap; row-gap:6px; }
  .rl-wrap { min-height:calc(100vh - 150px); margin-top:12px; }
  .rl-msg { max-width:94%; }
  .p6grid, .p5grid, .dgrid, .artgrid { grid-template-columns:1fr !important; display:block; }
}

/* ===== P14 想法池（H49） ===== */
.ideagrid { display:grid; grid-template-columns:repeat(auto-fit, minmax(260px, 1fr)); gap:14px; }
.idea { padding:16px 18px 12px; display:flex; flex-direction:column; gap:8px; }
.idea .it { font-size:14px; line-height:1.6; white-space:pre-wrap; }
.idea .in2 { font-size:12px; color:var(--ink3); }
.idea .ia { display:flex; align-items:center; gap:8px; margin-top:4px; }
.idea .ia .sp { flex:1; }

/* ===== P16 Wiki（0.20）：三栏词条布局 · 双链 · 待审卡 ===== */
.wk-tools { display:flex; gap:10px; align-items:center; margin:18px 0 14px; }
.wk-grid { display:grid; grid-template-columns: 170px minmax(0,1fr) 210px; gap:16px; align-items:start; }
.wk-tree { border-right:0.5px solid var(--line); padding-right:12px; font-size:13px; }
.wk-cat { margin:0 0 8px; font-weight:600; }
/* 词条行是块级（一行一条，整行可点）：地板靠纵向 padding 补足（21→27px），
   同步把行间距 6→3px 匀回来——列表节拍只多 3px，视觉上仍是原来那份密度（施工令-044 F3）。 */
.wk-it { margin:0 0 3px 16px; padding:3px 2px; color:var(--ink2); cursor:pointer; border-radius:6px; }
.wk-it:hover { color:var(--ink); }
.wk-it.cur { color:var(--accent-ink); font-weight:600; }
/* 触点地板 ≥26px（W32 补巡 · 施工令-030）：词条内链原先只有一行文字高（~17px），
   在触屏与小鼠标上都难点。**保持 inline** 只加纵向 padding——行内元素的纵向 padding
   会撑大命中盒却不改变行盒高度，于是触点够了、正文行距一个像素没动（改 inline-block
   会把 wiki 正文的段落行距整体拉开，那就越界了）。 */
.wk-l { color:var(--accent-ink); cursor:pointer; padding:5px 2px; }
.wk-l:hover { text-decoration:underline; }
/* 裸引导链（决策台空态「想法池拍板 / 工单池待投区」）：同一条地板，同一种做法 */
.glink { color:var(--accent-ink); cursor:pointer; padding:5px 2px; }
.glink:hover { text-decoration:underline; }
.wk-l.ghost { opacity:.55; border-bottom:1px dashed var(--accent-ink); }
.wk-body { line-height:1.85; font-size:14px; }
.wk-body p { margin:0 0 12px; }
.wk-body ul { margin:0 0 12px 18px; padding:0; }
.wk-body li { margin-bottom:4px; }
.wk-h { margin:16px 0 8px; }
/* 正文表格（施工令-017）：窄屏自己横滚，绝不撑破三栏 */
.wk-tw { overflow-x:auto; margin:0 0 12px; }
.wk-t { width:100%; border-collapse:collapse; font-size:12.5px; line-height:1.6; }
.wk-t th { text-align:left; font-weight:600; color:var(--ink); border-bottom:1.5px solid var(--line); padding:6px 9px; white-space:nowrap; }
.wk-t td { border-bottom:0.5px solid var(--line); padding:6px 9px; vertical-align:top; color:var(--ink2); }
.wk-t td:first-child { color:var(--ink); white-space:nowrap; }
.wk-t tr:last-child td { border-bottom:none; }
.wk-back { border-top:0.5px solid var(--line); margin-top:16px; padding-top:10px; }
/* 词条溯源链（施工令-015）：源文档 → 策划案/技术方案分区那一篇 */
.wk-src { margin:0; font-size:12.5px; color:var(--ink3); display:flex; flex-wrap:wrap; gap:6px; align-items:baseline; }
.wk-pend { display:flex; gap:10px; align-items:center; padding:10px 14px; margin-bottom:8px; background:var(--gatebg); border:1px solid var(--gateln); border-radius:12px; }
@media (max-width: 680px) { .wk-grid { grid-template-columns: 1fr; } .wk-tree { border-right:none; } }

/* ===== 协同策划文档 codoc（施工令-017）：块级编辑 + 作者色带 =====
   作者三档各占一色，只读态与编辑态同色——扫一眼就知道这段是谁写的。
   金 bronze=制作人 / 墨 ink=总监 / 青 teal=策划 / 灰=未知（老稿没戳） */
.cd-blk { position:relative; padding:2px 0 2px 14px; margin:0 0 4px; border-left:3px solid var(--cd-c, var(--ink3)); border-radius:2px; }
.cd-blk:hover { background:var(--sect); }
.cd-blk[data-a="制作人"] { --cd-c:#A16207; }
.cd-blk[data-a="总监"]   { --cd-c:#4B5563; }
.cd-blk[data-a="策划"]   { --cd-c:#0E7490; }
.cd-blk[data-a="未知"]   { --cd-c:var(--line); }
html[data-theme="glass"] .cd-blk[data-a="制作人"] { --cd-c:#E8B45A; }
html[data-theme="glass"] .cd-blk[data-a="总监"]   { --cd-c:#9BA6B5; }
html[data-theme="glass"] .cd-blk[data-a="策划"]   { --cd-c:#4CC3E0; }
.cd-blk .wk-body p:last-child, .cd-blk .wk-body ul:last-child { margin-bottom:0; }
/* 块工具条：只读态不占位，编辑态常显 */
.cd-ops { display:flex; gap:6px; align-items:center; margin:4px 0 10px; opacity:0; transition:opacity .12s var(--ease-out); }
.cd-blk:hover .cd-ops, .cd-blk:focus-within .cd-ops, .cd-blk.ed .cd-ops { opacity:1; }
.cd-blk.ed { padding-top:8px; padding-bottom:2px; }
.cd-sig { font-size:11.5px; color:var(--ink3); margin-left:auto; letter-spacing:.02em; }
.cd-ta { width:100%; min-height:96px; font:13px/1.7 var(--mono); color:var(--ink); background:var(--inbg);
  border:1px solid var(--line); border-radius:10px; padding:10px 12px; resize:vertical; box-shadow:inset 0 1px 2px var(--groove-soft); }
.cd-ta:focus { outline:none; border-color:var(--accent); box-shadow:0 0 0 3px var(--accent-glow); }
/* 图例 */
.cd-lg { display:flex; flex-wrap:wrap; gap:12px; align-items:center; font-size:12px; color:var(--ink2);
  padding:8px 12px; margin:0 0 14px; background:var(--sect); border:1px solid var(--line); border-radius:10px; }
.cd-lg i { display:inline-block; width:10px; height:10px; border-radius:2px; margin-right:5px; vertical-align:-1px; background:var(--cd-c); }
.cd-lg span[data-a] { --cd-c:var(--ink3); }
.cd-lg span[data-a="制作人"] { --cd-c:#A16207; }
.cd-lg span[data-a="总监"]   { --cd-c:#4B5563; }
.cd-lg span[data-a="策划"]   { --cd-c:#0E7490; }
.cd-lg span[data-a="未知"]   { --cd-c:var(--line); }
html[data-theme="glass"] .cd-lg span[data-a="制作人"] { --cd-c:#E8B45A; }
html[data-theme="glass"] .cd-lg span[data-a="总监"]   { --cd-c:#9BA6B5; }
html[data-theme="glass"] .cd-lg span[data-a="策划"]   { --cd-c:#4CC3E0; }
.cd-add { width:100%; margin:2px 0 12px; border-style:dashed; color:var(--ink3); }
.cd-add:hover { color:var(--accent-ink); border-color:var(--accent); }

/* 项管信道问答重做（0.23.2）：提问=右侧短气泡，回复=左对齐全宽文档块（含 markdown） */
.rl-doc { align-self:stretch; width:100%; }
.rl-doc .wk-body { background:var(--sect); border:1px solid var(--line); border-radius:14px; border-top-left-radius:4px; padding:12px 16px; font-size:13.5px; }
.rl-doc .wk-body p { margin:0 0 10px; }
.rl-doc .wk-body p:last-child { margin-bottom:0; }

/* 折叠摘要行（0.23.3）：台账/汇报流默认收起，对话区优先 */
.rl-fold { margin-bottom:10px; }
.rl-fold > summary { cursor:pointer; font-size:12.5px; color:var(--ink2); padding:8px 14px; background:var(--sect); border:1px solid var(--line); border-radius:10px; list-style:none; }
.rl-fold > summary::-webkit-details-marker { display:none; }
.rl-fold[open] > summary { border-bottom-left-radius:0; border-bottom-right-radius:0; }
.rl-fold > div { border:1px solid var(--line); border-top:none; border-radius:0 0 10px 10px; padding:12px 16px; }

/* 管线头行（0.23.4）已随施工令-022 退役：管线不再是画布里的一条区块标题，它就是甘特的一整行（.fghead）。 */

/* 施工令-005：在途原地展开区已删（与卡片本体信息重复），整卡点击直达详情页。
   agdIn 关键帧保留——确认层 .ask-ov 仍在用。 */
@keyframes agdIn { from { opacity:0; transform:translateY(-4px); } to { opacity:1; transform:none; } }

/* 2026-08-06 UI 评审 · hub 页：H-1 最近动态行 / H-2 零值灰显 / H-3 焦点环 */
.hubcard .hlast { font-family:var(--mono); font-size:10.5px; color:var(--ink3); margin-top:10px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; min-height:14px; }
.hubcard .hc i.z { color:var(--ink3); font-weight:500; }
.hubcard:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.inbox-row:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
/* 施工令-005：在跑卡整卡可点（直达详情页），补指针与焦点环 */
.arow2[role="button"] { cursor:pointer; }
.arow2[role="button"]:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }

/* 应用内确认层（confirm 哑弹案，2026-08-06）：mask 铺底 + 居中卡，浏览器与 exe 同行为 */
.ask-ov { position:fixed; inset:0; background:var(--mask); display:flex; align-items:center; justify-content:center; z-index:60; animation:agdIn .15s var(--ease-out); }
.ask-ov .ask-card { min-width:300px; max-width:420px; padding:22px 24px; box-shadow:var(--shadow-lg); }
.ask-ov .ask-card p { font-size:13.5px; color:var(--ink); line-height:1.6; margin:0; }
/* 自绘输入层（施工令-012）：与确认层同一视觉家族，替下 Electron 壳内哑弹的原生 prompt() */
.ask-ov .ask-card .askin { display:block; width:100%; box-sizing:border-box; height:36px; margin-top:12px;
  padding:0 12px; font-size:13px; border-radius:9px; border:1px solid var(--line);
  background:var(--paper); color:var(--ink); }
.ask-ov .ask-card .askin:focus { outline:none; border-color:var(--accent); }
.ask-ov .ask-card .asknote { margin-top:8px; font-size:11px; color:var(--ink3); line-height:1.5; }
@media (prefers-reduced-motion: reduce) { .ask-ov { animation:none; } }

/* 短题制兜底（H83，施工令-002）：卡片标题统一两行截断，悬停 title 显全文；详情页不套此类 */
.clamp2 { display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; line-clamp:2;
  overflow:hidden; text-overflow:ellipsis; white-space:normal; word-break:break-word; line-height:1.35; }
/* 下面三条只为压过原「nowrap 单行省略」的更高特指度声明，规则本体仍在 .clamp2 */
.inbox-row .rt.clamp2 { flex:0 0 170px; white-space:normal; }
.bcard2 .ct.clamp2 { display:-webkit-box; white-space:normal; }

/* 工程队状态卡（施工令-002）：只读一行卡，无状态文件时整卡不渲染 */
/* 工程队卡（施工令-002 立卡 · 041 直读 · 042 扩成队列卡）：
   顶行仍是「当前施工令」那一行（.cwtop 保留原来的横排口径），其下挂 Q 队列精简行。 */
.crewcard { display:block; padding:12px 20px; margin-top:16px; }
.crewcard .cwtop { display:flex; align-items:center; gap:12px; }
.crewcard .cwo { font-size:11px; color:var(--ink3); }
.crewcard .cwn { font-size:12.5px; color:var(--ink2); max-width:420px; }
.crewcard .spacer { flex:1; }
/* ---- 042 §二：hub 队列区（精简版行——它不可点，因为还没有工单可点） ---- */
.crewq { margin-top:10px; padding-top:8px; border-top:1px dashed var(--line); }
.crewq .cqh { display:flex; align-items:center; gap:6px; font-size:11px; color:var(--ink3); margin-bottom:4px; }
.crewq .cqh b { font-family:var(--mono); color:var(--ink2); }
.crewq .cqh .sp { flex:1; }
.crewq .cqmore, .crewq .cqmoreline a { color:var(--accent-ink); text-decoration:none; }
.crewq .cqmore:hover, .crewq .cqmoreline a:hover { text-decoration:underline; }
.cqrow { display:flex; align-items:center; gap:8px; padding:3px 6px; border-radius:6px; min-width:0; }
.cqrow:hover { background:var(--we); }
.cqrow .cqs { font-size:10.5px; color:var(--ink3); white-space:nowrap; }
.cqrow .cqb { font-size:10px; padding:0 6px; border-radius:999px; white-space:nowrap;
  color:var(--ink3); border:1px dashed var(--ink3); }
.cqrow .cqt { flex:1 1 0; width:0; min-width:0; font-size:12px; color:var(--ink2);
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.cqrow .cqw { font-size:10px; color:var(--danger); white-space:nowrap; }
.cqrow .cqe { font-size:10.5px; color:var(--ink3); white-space:nowrap; }
.cqrow.blocked { opacity:.6; }
.crewq .cqempty, .crewq .cqmoreline { font-size:11px; color:var(--ink3); padding:3px 6px; }

/* ===== P12b 队列页（施工令-042 §一）：按 批→序 铺全量计划粒 =====
   与流程页共用语义令牌，但形态相反：流程页是「一行一管线的横切」，本页是「一块一批的竖列」。
   条不可点（无工单可点），只有已成单的粒把单号做成链——点错地方跳 404 是比看不见更差的体验。 */
.qtop { display:flex; align-items:baseline; gap:14px; flex-wrap:wrap; margin-top:22px; }
.qtop .sp { flex:1; min-width:0; }
.qsum { font-family:var(--mono); font-size:13px; color:var(--ink); font-weight:700; }
.qboard { margin-top:12px; display:flex; flex-direction:column; gap:10px; }
.qbatch { border:1px solid var(--line); border-radius:12px; background:var(--card); box-shadow:var(--shadow-sm); overflow:hidden; }
.qbh { display:flex; align-items:center; gap:8px; padding:9px 14px; cursor:pointer; background:var(--sect);
  border-bottom:1px solid var(--line); min-height:38px; }
.qbh:hover, .qbh:focus-visible { background:var(--we); outline:none; }
.qbh b { font-size:13px; }
.qbh .qbn { font-size:11px; color:var(--ink3); }
.qbh .qbe { font-size:11.5px; color:var(--ink3); white-space:nowrap; }
.qbh .sp { flex:1; min-width:0; }
.qbh .qcar { color:var(--ink3); font-size:11px; transition:transform .14s var(--ease-out); }
.qbatch.fold .qbh { border-bottom:none; }
.qbatch.fold .qbh .qcar { transform:rotate(-90deg); }
.qbatch.fold .qrows { display:none; }
.qbatch.done .qbh b { color:var(--ink2); }
.qrows { padding:6px 10px 8px; }
.qrow { display:flex; align-items:center; gap:9px; padding:5px 8px; border-radius:7px; min-width:0;
  border:1px solid transparent; }
.qrow:hover { background:var(--we); border-color:var(--line); }
.qrow .qs { font-size:11px; color:var(--accent-ink); white-space:nowrap; }
.qrow .qt { flex:1 1 0; width:0; min-width:0; font-size:12.5px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.qrow .qtk { font-size:11px; color:var(--accent-ink); text-decoration:none; white-space:nowrap; }
.qrow .qtk:hover { text-decoration:underline; }
.qrow .qsrc { font-size:10.5px; color:var(--ink3); max-width:220px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.qrow .qest { font-size:11px; color:var(--ink3); white-space:nowrap; min-width:52px; text-align:right; }
.qrow .qpool { font-size:10px; color:var(--ink3); border:1px solid var(--line); border-radius:999px; padding:0 6px; white-space:nowrap; }
/* 状态徽章五型：计划/起草中还没成单（虚框，弱于任何真单）；已成单起用实调；终态退成灰字 */
.qrow .qb { font-size:10px; padding:1px 7px; border-radius:999px; white-space:nowrap; color:var(--ink3);
  border:1px dashed var(--ink3); background:transparent; }
.qrow .qb.draft { color:var(--gatetx); border-color:var(--gateln); background:var(--gatebg); }
.qrow .qb.made { color:var(--accent-ink); border:1px solid var(--accent-ink); }
.qrow .qb.done { color:var(--ok); border:1px solid var(--okln); }
.qrow .qb.drop { color:var(--ink3); border-style:dotted; text-decoration:line-through; }
/* 依赖未满足：置灰 + 红字「候：X」——本页最要紧的一句话是「这条为什么还不能开」 */
.qrow.blocked { opacity:.55; }
.qrow.blocked:hover { opacity:.9; }
.qrow .qwait { font-size:10px; color:var(--danger); border:1px solid var(--danger); background:var(--dangerbg);
  border-radius:999px; padding:1px 7px; white-space:nowrap; }
/* 终态行整行退让：它们在场只为当「还剩几件」的分母 */
.qrow.fin { opacity:.62; }
.qrow.fin:hover { opacity:1; }
.qrow.fin .qt { color:var(--ink3); }
@media (max-width:860px) {
  .qrow { flex-wrap:wrap; }
  .qrow .qsrc { max-width:100%; }
  .qrow .qt { flex:1 1 100%; width:auto; }
}

/* ===== 挂起（施工令-021 · 制作人裁决权）：全站置灰 + ❄ 徽标 =====
   语义：挂起是「制作人按下了冻结」，不是坏了也不是没人管——所以用降饱和的冷调，
   不用告警红。三处渲染（工单池卡 / 在途时间轴段 / 流程视图）共用这一组类，
   任何新视图只要挂上 .susp 就自动同款，不必各画各的。
   施工令-022 起流程视图不再有 .fl-node：挂起单在新流程页只出现在沉淀抽屉的 ❄ 类里（.fgsi.susp），
   现在/接下来两段一律跳过——「全链路跳过」在视图层的兑现。 */
.susp { filter:grayscale(.85); opacity:.55; }
.susp:hover { opacity:.8; }
.bcard2.susp { border-style:dashed; }
.tlseg.susp { opacity:.35; filter:grayscale(1); }
.pill.susp-p { background:var(--chip); color:var(--ink3); font-weight:600; letter-spacing:.02em; }
/* 徽标本身不跟着置灰——它是「为什么灰」的答案，灰掉就白标了 */
.susp .snowb, .snowb { filter:none; opacity:1; }
.bcard2 .snowb { font-size:11px; margin-right:4px; }

/* 详情页「已挂起」横幅：顶在最上层，解挂按钮就在横幅里——制作人不必去操作栏里翻 */
.suspbar { display:flex; align-items:center; gap:12px; flex-wrap:wrap; padding:12px 18px;
  margin-bottom:14px; border-radius:14px; background:var(--chip); border:1px dashed var(--ink3); color:var(--ink2); }
.suspbar b { font-size:13px; color:var(--ink); }
.suspbar .sbwho { font-size:12px; color:var(--ink3); }
.suspbar .sbwhy { font-size:12px; color:var(--ink2); flex-basis:100%; line-height:1.5; }
.suspbar .sp { flex:1; }
@media (prefers-reduced-motion: reduce) { .susp:hover { opacity:.55; } }

/* ===== 关键汇报 · 一单一链事件链（施工令-037，制作人 2026-08-09 18:34 批准设计稿）=====
   语义色三档，全部走既有令牌，不新造色也不写裸 hex（双主题自动跟随）：
     绿 --ok        = 终态（完成/归档，默认折叠成一行）
     橙 --now       = 在途（机闸：执行/判官在跑）——全站唯一「此刻正在发生」色，与流程视图现在线同源
     靛 --accent-ink= 等人闸（人闸：等制作人/总监签字放行）——设计稿夜间那档 #9D93FF 正是本令牌夜值
   几何：链条一根 2px 竖线 + 每站一颗圆点，与 .logrow 同一时间列宽（52px）以求列对齐。 */
.kchain { margin-top:12px; }
.kitem { border-top:1px solid var(--line); padding:8px 2px; }
.kitem:first-child { border-top:0; }
.khead { display:flex; align-items:center; gap:10px; cursor:pointer; padding:3px 2px; border-radius:8px;
  transition:background .16s var(--ease-out); }
.khead:hover { background:var(--sect); }
.karrow { color:var(--ink3); font-size:11px; width:10px; flex:none; }
.kid { font-weight:600; font-family:var(--mono); font-size:12.5px; color:var(--ink); text-decoration:none; flex:none; }
.kid:hover { color:var(--accent); text-decoration:underline; }
.ktitle { color:var(--ink2); flex:1; min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-size:13px; }
.kst { font-size:11px; border-radius:999px; padding:2px 10px; flex:none; font-weight:600; white-space:nowrap; }
.kst.done { background:var(--okbg); color:var(--ok); }
.kst.doing { background:var(--nowtint); color:var(--now); }
.kst.wait { background:var(--accenttint); color:var(--accent-ink); }
/* 折叠：只藏链体，头行永远在（完成单折一行 = 一行说清「什么时候被谁收的」） */
.kbody { display:none; }
.kitem.open .kbody { display:block; }
.kline { margin:8px 0 4px 6px; padding-left:14px; border-left:2px solid var(--line); }
.kstep { position:relative; padding:3px 0 3px 10px; font-size:12.5px; color:var(--ink2); line-height:1.55; }
.kstep::before { content:''; position:absolute; left:-19px; top:10px; width:8px; height:8px; border-radius:50%;
  background:var(--ok); }
.kstep .kt { color:var(--ink3); font-family:var(--mono); font-size:11.5px; display:inline-block;
  width:52px; flex:none; }
.kstep .kx { color:var(--ink); }
.kstep .kwhy { color:var(--ink3); }
/* 现在行：橙点带光晕——「此刻停在哪」必须一眼跳出来 */
.kstep.now { color:var(--now); }
.kstep.now .kx, .kstep.now .kt { color:var(--now); font-weight:600; }
.kstep.now::before { background:var(--now); box-shadow:0 0 0 3px var(--nowtint); }
.kstep.fin::before { background:var(--ok); box-shadow:0 0 0 3px var(--okbg); }
.kstep.fin .kx { color:var(--ok); font-weight:600; }
/* 缺站行：如实说「没有就是没有」，不伪装成一个站 */
.kstep.kmiss { color:var(--ink3); font-style:italic; }
.kstep.kmiss::before { background:var(--line); }
/* 尾端「现在等什么」：人闸靛、机闸橙——颜色本身就在回答「该我动手了吗」 */
.kfoot { font-size:12px; padding:6px 0 2px 10px; margin-left:6px; }
.kfoot.human { color:var(--accent-ink); }
.kfoot.mach { color:var(--now); }
.kfoot b { font-weight:600; }
@media (max-width:720px) {
  .ktitle { display:none; } /* 窄屏先舍标题：单号与徽章是最小可用信息 */
  .kstep .kt { width:44px; }
}

