426	/* 工单页长列折叠（施工令-044 F5）：只对「完成」列生效——它是唯一只增不减的列。
427	   最近＝交付时间倒序（缺交付时间的回落更新时间/创建时间，一律不参与「最近」的前排）。
428	   展开态落 localStorage：制作人把它展开过一次，回来还是展开的。 */
429	const BOARD_FOLD_N = 10;
430	const FOLD_STATES = new Set(['完成']);
431	const foldKey = (s) => 'studio-board-open-' + s;
432	const boardOpen = (s) => { try { return localStorage.getItem(foldKey(s)) === '1'; } catch { return false; } };
433	const boardRecent = (arr) => [...arr].sort((a, b) =>
434	  String(b.交付时间 || b.更新时间 || b.创建时间 || '').localeCompare(String(a.交付时间 || a.更新时间 || a.创建时间 || ''))
435	  || String(b.id).localeCompare(String(a.id)));
436	window.boardFold = (s) => {
437	  try { localStorage.setItem(foldKey(s), boardOpen(s) ? '0' : '1'); } catch { /* 隐私模式：本次会话内不记忆 */ }
438	  route();
439	};
440	async function viewBoard() {
441	  const { states, board } = await loadBoard();
442	  const conf = await api('/api/config').catch(() => ({ 闸值: {} }));
443	  const widths = { 池: 'w168', 在途: 'w168', 待验收: 'w168', 执行失败: 'w128', 完成: 'w128', 已归档: 'w128' };
444	  const cols = states.map((s) => {
445	    // 完成列折叠（施工令-044 F5 · 巡礼）：落袋单只增不减，百来张平铺下去，工单页一开就是一屏
446	    // 「已经做完的事」——找在办的单反而要滚很久。默认只留最近 10 张（交付时间倒序，最近的在最上），
447	    // 其余收进一个「展开全部 N 条」钮里。总数不藏：列头 .cnt 永远报全量。展开态记本地（换页/重启都记得）。
448	    const 折 = FOLD_STATES.has(s);
449	    const items = 折 ? boardRecent(board[s] || []) : (board[s] || []);
450	    const 收 = 折 && items.length > BOARD_FOLD_N && !boardOpen(s);
451	    const 可见 = 收 ? items.slice(0, BOARD_FOLD_N) : items;
452	    const hot = s === '待验收' || s === '待定夺' || s === '执行失败';
453	    const head = s === '草稿'
454	      ? `<h4>${s}<a class="newdraft" href="#/draft">＋ 起草</a></h4>`
455	      : s === '待投' && items.length
456	        ? `<h4>${s}<button class="newdraft" title="整批放行（H49 派发制：放行后依赖就绪即自动派发；人闸就是这一下）" onclick="releaseAll()">⇧ 全放行 ${items.length}</button></h4>`
457	        : s === '已归档' && (window._hiddenCnt || window._showHidden)
458	          ? `<h4>${s}<span class="cnt">${items.length}</span><button class="newdraft" title="隐藏归档：制作人湮灭的废案，默认不渲染" onclick="window._showHidden=!window._showHidden;route()">${window._showHidden ? '藏起' : `显隐藏 ${window._hiddenCnt}`}</button></h4>`
459	          : `<h4>${s}<span class="cnt">${items.length}</span></h4>`;
460	    const cards = 可见.map((t) => `<div class="bcard2${suspCls(t)}" data-tid="${esc(t.id)}" onclick="location.hash='#/t/${t.id}'"${suspOf(t) ? ` title="${esc(suspTip(t))}"` : ''}>
461	        <span class="cid">${snowB(t)}${esc(t.id)}</span>
462	        <span class="cpri ${t.优先级 === 'P0' ? 'p0' : ''}">${esc(t.优先级 || '')}</span>
463	        <div class="ct clamp2" title="${esc(t.title)}">${esc(t.title)}</div>${fnPill(t.职能)}</div>`).join('');
464	    const 折钮 = 折 && items.length > BOARD_FOLD_N
465	      ? `<button class="bmore" onclick="boardFold('${qesc(s)}')" title="${收 ? '这一列只显示了最近 10 张' : '收回只看最近 10 张'}">${收 ? `展开全部 ${items.length} 条` : `收起 · 只看最近 ${BOARD_FOLD_N} 条`}</button>`
466	      : '';
467	    return `<div class="bcol2 ${widths[s] || ''} ${hot ? 'hot' : ''}">${head}${cards}${折钮}</div>`;
468	  }).join('');
469	  const fillBar = async () => {
470	    const g = await api('/api/gates'); gateCache = g;
471	    const gb = $('gatebar-slot');
472	    if (gb) { const key = JSON.stringify([g.paused, g.locks.codex, g.locks.claude, g.推荐 && g.推荐.推荐]);
473	      if (gb.dataset.k !== key) { gb.dataset.k = key; gb.innerHTML = gatebarHtml(g); } }
474	    const bn = $('backlogN'); if (bn) bn.textContent = `${(board['待验收'] || []).length} / ${conf.闸值?.待验收积压闸 ?? 8}`;
475	  };

