      const hit = [...lines].reverse().find((l) => l.includes(n + '-') || l.includes('项目 ' + n));
      if (hit) { const m = String(hit).match(/^\[[^\]]*?([\d:]{5})[^\]]*\]\s*(.*)$/); el.textContent = (m ? m[1] + ' · ' + m[2] : hit).slice(0, 56); }
    }
