      `<span class="pp" id="fgp-${esc(t.id)}" title="${esc(p.提示)}">${p.百分比 == null ? '—' : p.百分比}<small>%</small></span><span class="st" id="fgs-${esc(t.id)}">${esc(p.阶段名)}</span>`);
  };
  const signBar = (t) => {
