// render.js — 在 node 里跑 public/app.js 的视图函数，取回真实 HTML（数据走本地桩台 4299）
// 用途：F3 触点清点 / F4 报表列 / F5 完成列折叠 / F6 空态行数 —— 四项都从真 DOM 串上量。
const fs = require('fs');
const vm = require('vm');
const path = require('path');

const APP = 'D:/GitHub/Ticketflow/apps/studio/public/app.js';
const BASE = 'http://127.0.0.1:4299';

function makeSandbox() {
  const store = { 'studio-theme': 'paper' };
  if (process.argv.includes('--open')) store['studio-board-open-完成'] = '1'; // F5 展开态复测
  const noopEl = () => ({
    classList: { add() {}, remove() {}, toggle() {}, contains: () => false },
    style: {}, dataset: {}, setAttribute() {}, removeAttribute() {}, getAttribute: () => null,
    appendChild() {}, remove() {}, focus() {}, select() {}, addEventListener() {},
    querySelector: () => null, querySelectorAll: () => [], closest: () => null,
    textContent: '', innerHTML: '', value: '', children: [], scrollLeft: 0, scrollWidth: 0, clientWidth: 0,
  });
  const document = {
    getElementById: () => null,
    querySelector: () => null,
    querySelectorAll: () => [],
    createElement: () => noopEl(),
    addEventListener() {},
    body: { appendChild() {}, contains: () => false, classList: { add() {}, remove() {} } },
    documentElement: { dataset: {}, classList: { add() {}, remove() {}, toggle() {} }, style: { setProperty() {} } },
  };
  const sandbox = {
    console,
    document,
    location: { hash: '#/', href: BASE + '/' },
    localStorage: {
      getItem: (k) => (k in store ? store[k] : null),
      setItem: (k, v) => { store[k] = String(v); },
      removeItem: (k) => { delete store[k]; },
    },
    matchMedia: () => ({ matches: false, addEventListener() {}, addListener() {} }),
    setTimeout: () => 0, clearTimeout: () => {}, setInterval: () => 0, clearInterval: () => {},
    requestAnimationFrame: () => 0,
    fetch: (p, opt) => fetch(p.startsWith('http') ? p : BASE + p, opt),
    addEventListener() {}, removeEventListener() {},
    JSON, Math, Date, Number, String, Object, Array, Set, Map, Promise, encodeURIComponent, decodeURIComponent, isNaN, parseInt, parseFloat,
    Intl, RegExp, Error, TextEncoder, TextDecoder, URL,
  };
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  return sandbox;
}

async function main() {
  const src = fs.readFileSync(APP, 'utf8').replace(/^route\(\);$/m, '/* boot route disabled */');
  const sb = makeSandbox();
  vm.createContext(sb);
  vm.runInContext(src, sb, { filename: 'app.js' });
  const out = {};
  const views = {
    agents: 'viewAgents', relay: 'viewRelay', wiki: 'viewWiki',
    board: 'viewBoard', flow: 'viewFlow', report: 'viewReport',
  };
  for (const [k, fn] of Object.entries(views)) {
    sb.location.hash = '#/' + k;
    try {
      out[k] = await sb[fn]();
    } catch (e) { out[k] = '<!-- ERROR ' + (e && e.stack || e) + ' -->'; }
  }
  // wiki 词条页（双链 .wk-l 只在打开某条词条后才出现）：单列一页
  sb.location.hash = '#/wiki';
  vm.runInContext("wkState.entry = '战斗节奏';", sb); // 顶层 const 不挂 global，得走同上下文再执行
  try { out['wiki-entry'] = await sb.viewWiki(); } catch (e) { out['wiki-entry'] = '<!-- ERROR ' + e + ' -->'; }
  const dir = path.join(__dirname, process.argv.includes('--after') ? 'html-after' : 'html-before');
  fs.mkdirSync(dir, { recursive: true });
  for (const [k, html] of Object.entries(out)) fs.writeFileSync(path.join(dir, k + '.html'), html, 'utf8');
  console.log('WROTE ' + dir);
  for (const [k, html] of Object.entries(out)) console.log(k, html.length, /ERROR/.test(html.slice(0, 200)) ? html.slice(0, 400) : '');
}
main();

