function makeSandbox() {
  const store = { 'studio-theme': 'paper' };
  if (process.argv.includes('--open')) store['studio-board-open-完成'] = '1'; // F5 展开态复测
  const noopEl = () => ({
    classList: { add() {}, remove() {}, toggle() {}, contains: () => false },
    style: {}, dataset: {}, setAttribute() {}, removeAttribute() {}, getAttribute: () => null,
    appendChild() {}, remove() {}, focus() {}, select() {}, addEventListener() {},
    querySelector: () => null, querySelectorAll: () => [], closest: () => null,
    textContent: '', innerHTML: '', value: '', children: [], scrollLeft: 0, scrollWidth: 0, clientWidth: 0,
  });
  const document = {
    getElementById: () => null,
    querySelector: () => null,
    querySelectorAll: () => [],
    createElement: () => noopEl(),
    addEventListener() {},
    body: { appendChild() {}, contains: () => false, classList: { add() {}, remove() {} } },
    documentElement: { dataset: {}, classList: { add() {}, remove() {}, toggle() {} }, style: { setProperty() {} } },
  };
  const sandbox = {
    console,
