        <div class="rsec"><div class="rl">回执原文</div><div class="rv mono" style="white-space:pre-line">${esc(tail || '（回执为空文件）')}</div></div>`;
    };
    const 轮s = 回执分轮(d.回执.raw);
    if (轮s.length <= 1) {
